window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["3609132"]={"book":{"id":3609132,"title":"把时间当作朋友","author":"李笑来","translator":"","publisher":"电子工业出版社","pubdate":"2009-6","isbn":"9787121087097","tags":["时间管理","自我管理","李笑来","心智","成长","个人管理","励志","思维"],"memCount":20},"np":1,"pb":[25],"idx":[{"i":14480,"t":"认识五种时间，优化时间管理","l":"TF3-3","c":"原来是锋哥啊","g":1,"p":1},{"i":9099,"t":"建立你的“验收机制”。","l":"TF1-2","c":"刘超军","g":1,"p":1},{"i":8328,"t":"让节奏慢下来","l":"TF2-3","c":"Sophia Ho","g":1,"p":1},{"i":8122,"t":"建立你的“验收机制”","l":"TF1-2","c":"刘超军","g":1,"p":1},{"i":8093,"t":"有效倾听的3个技巧！","l":"TF1-1","c":"刘超军","g":1,"p":1},{"i":4661,"t":"正确复述","l":"TF1-1","c":"姜莹莹","g":1,"p":1},{"i":4371,"t":"普通人如何加速成长？先学会独立思考！","l":"TF3-3","c":"馒头","g":1,"p":1},{"i":4370,"t":"如何做出短期有效的计划？","l":"TF1-2","c":"方凯","g":1,"p":1},{"i":4368,"t":"学习独立思考，让你的脑子更清楚","l":"TF3-3","c":"馒头","g":1,"p":1},{"i":3972,"t":"做事情最好的开始时间是现在","l":"TF1-2","c":"风信子","g":1,"p":1},{"i":3437,"t":"预先演练工作法","l":"TF1-1","c":"英爱","g":1,"p":1},{"i":3326,"t":"积极鼓励别人","l":"TF1-1","c":"Andy.Guo","g":1,"p":1},{"i":3281,"t":"做一个“给力“”的倾听者","l":"TF1-1","c":"Shooshoo","g":1,"p":1},{"i":3246,"t":"预演","l":"TF1-1","c":"树袋熊贝贝","g":1,"p":1},{"i":2937,"t":"把时间当朋友","l":"TF1-1","c":"树袋熊贝贝","g":1,"p":1},{"i":2903,"t":"能够正确面对不满意的现状，进而获知进步的关键策略。","l":"TF2-1","c":"李明","g":1,"p":1},{"i":1944,"t":"兴趣不是天生的，而是后天反复习得的技能","l":"TF1-1","c":"小猴儿精","g":1,"p":1},{"i":1670,"t":"6个方法，拯救拖拉，提升效率","l":"TF2-1","c":"悠南","g":1,"p":1},{"i":1524,"t":"学会倾听","l":"TF3-1","c":"朱依凌（鱼小刺）","g":1,"p":1},{"i":855,"t":"做到倾听时让别人倾诉","l":"TF3-1","c":"存在","g":1,"p":1},{"i":697,"t":"想与时间做朋友？你要先学会这一招～","l":"TF2-2","c":"王小桃","g":0,"p":1},{"i":627,"t":"如何善用你的社交时间？","l":"TF3-2","c":"熊赳赳爱学习","g":0,"p":1},{"i":361,"t":"TF1-1练习","l":"TF1-1","c":"雪野兔","g":0,"p":1},{"i":353,"t":"沟通","l":"TF2-4","c":"卢珊","g":0,"p":1},{"i":87,"t":"如何高效的一心二用","l":"TF1-2","c":"吴桐","g":1,"p":1}],"ms":[{"id":14480,"topic":"认识五种时间，优化时间管理","learn_goal":"","remark":"学习、打工或是创业中的你，是否总觉得光阴似箭，或者困惑于在工作或生活的意义？尝试运用“五种时间”方法论来规划时间、重建人生秩序吧。","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"原来是锋哥啊","city":""},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>30秒\u003cbr>大家好，我是锋哥，一个在IT行业从业二十年的“老人”，也是一位连续拆书升级挑战者。加入分舵刚满三个月，读的书已经超过之前三年的总和。拆书让我们交到了很多朋友，也深入思考了很多问题，感谢拆书帮申活分舵，感谢各位伙伴和我一起分享求知的快乐\u003c/p>\u003cp>\u003cstrong>【场景介绍法】\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>【场景】\u003c/strong>\u003cbr>上个月我们部门做绩效面谈的时候，一位做开发的同事和我说他很迷茫。写了两年的程序，感觉技术上一直在原地踏步。已经有倦怠感了，但也不知道自己还可以做点什么其他的事情。他不甘心就这样下去，可是也不知道该怎么去努力。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【提问】\u003c/strong>\u003cbr>今天在座的小伙伴们都很年轻，正是梦想和拼搏的年纪，那你们有没有过类似的困惑呢？你能看清此刻的努力和未来的梦想之间的联系吗？是不是也曾经在某个时刻感叹：“我的人生不会就这样了吧？”\u003cbr>\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003cbr>人是追求意义的动物，这种意义很大程度上来源于我们对人生的规划。如果规划清晰，我们会充满斗志，遇到再多困难我们也可以坚决地去克服；而一旦不清晰，则会让我们陷入困顿与迷茫，会降低我们的工作的工作效率、影响我们的生活幸福感、甚至造成抑郁与疾病。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003cbr>我们对人生的规划体现为对时间的运用。而要运用好时间首先需要正确地定义时间。今天我们要分享的这本书叫《五种时间.重建人生秩序》，它为我们提供了一个定义时间的坐标系叫“五种时间”，我们可以使用它来对自己现在以及未来的时间进行归类，为进一步的规划做好准备。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>30秒\u003cbr>今天我们学习的第一个目标，是希望大家能理解“五种时间”的模型，并（辨析）运用“五种时间”模型来对自己目前每天所花费的时间进行归类（行为），产出时间分析表（效果）。\u003c/p>","ratings_count":1,"texts":[{"id":18492,"quote":"\u003cp>用有限的时间去换一切，当然很难，但是我们有办法做到。那就需要从现在开始，把时间看成你的资源，分配到各个目标B里去。你还需要对写下的所有目标B做排列和归纳，看从哪里开始做起，因为整个“五种时间”之旅，就是从对目标B的分类开始的。研究按照需求应该从哪里开始展开行动，这些持续的行动会形成你的结构、你的质地。\u003cbr>正如这本书的名字，接下来，从第二章起，我们日常所从事的事务都可以被分成五种时间，它们分别是\u003cstrong>生存时间、赚钱时间、好看时间、好玩时间、心流时间\u003c/strong>。它们有各自清晰的分类和定义，也有着规律性的进阶关系。这本书将为你全面分析和讲述它们的操作方式，引导你建立起你的结构，当你完全了解和应用之后，你就掌握了时间管理的全部真谛。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>【互动提问】\u003c/strong>\u003cbr>看完拆页，哪位伙伴能回答我一个问题，作者定义的五种时间分别是什么？\u003cbr>路飞：生存时间、赚钱时间、好看时间、好玩时间和心流时间\u003cbr>回应：非常好，这5种时间我们可以分为3类，其中生存时间和赚钱时间是一类，好看时间和好玩时间是一类，心流时间是一类，你看我们桌上摆的这三组道具，就按照不同的颜色做了标识\u003c/p>\u003cp>下面我们增加难度了，接下来谁能帮我解释一下什么是生存时间？\u003cbr>楚楚：是我们在这个世界上需要睡觉的时间，就叫生存时间。\u003c/p>\u003cp>【向学习者提问】：所以，生存时间就等于睡觉时间？\u003c/p>\u003cp>楚楚：一日三餐这种时间也可以算\u003c/p>\u003cp>【向学习者提问】：这个答案已经很接近了，有没其他答案呢？\u003c/p>\u003cp>楚楚：维持生存所需要的时间\u003cbr>回应：非常好，生存时间顾名思义，就是为了生存所花费的时间。通常我们生活中为了生存所花费的时间有哪些呢？吃饭、睡觉、看病、还有最常见的上班\u003c/p>\u003cp>\u003cbr>那接下来谁能帮我解释一下什么是赚钱时间？\u003cbr>路飞：就是打工仔一天8小时赚钱的时间，也就是工作的时间\u003cbr>回应：很好，赚钱时间和赚钱有关，但并不是能赚钱的时间都叫赚钱时间。他们的区别在哪里？如果我们这个时间是花在打磨和提升自己的核心能力上，是在为自己的事业、或为了将来能成就自己的视野而做准备，那才叫赚钱时间。如果是在为别人打工，并对自己没有积累和成长，虽然能拿到工资也只能算生存时间。\u003c/p>\u003cp>接下来是好看时间和好玩时间，这两个时间都是花在和收入无关的方面的时间，前者呢是用来加强自己的身体，让自己变得更加招人喜欢，更有魅力。比如说我今天去给自己选了一套新衣服，把自己打扮得更漂亮、更有气质，或者说我今天去健身，让自己的身材更好，这都是好看时间。后者是用来满足自己的兴趣或好奇心，增长见识，提升修养。比如说我到世界各地去旅游，增长见识，就算好玩时间；我花了一个下午把家里的花拾掇了一下，或者花了一个星期把海贼王的手办做成了，这也是好玩时间。\u003c/p>\u003cp>最后是心流时间，它表示的是处于心流状态的时间，什么叫心流？简单地说心流就是当你做一件事儿的时候沉浸其中，你已经意识不到外界甚至自己的存在了，这个时候就可以说处于心流状态。心流状态可能在做任何事情的时候发生，所以心流时间可以和前面任何一种时间相重合。 \u003c/p>\u003cp>\u003cstrong>【学习者互动】\u003c/strong>\u003c/p>\u003cp>nancy：那我在家带娃算是什么时间呢？\u003c/p>\u003cp>回应：这个我等下来讲\u003cbr>\u003cbr>\u003cstrong>【概念辨析】\u003c/strong>\u003cbr>下面我们来举几个例子帮助大家来辨析这五种时间的概念。以我们熟悉的“骑车”为例，我拿现场的伙伴做一个角色扮演，请不要介意哦：\u003cbr>\u003cbr>□路飞每天都要骑1个小时的车去上班。那这1个小时对路飞来说算什么呢？是工作需要，所以算生存时间。\u003cbr>□安雨和亚茹是闺蜜，她们相约周末都到外环绿地去骑行10公里，所以对她们来说，骑行是健身，可以让自己身材更好，所以是好看时间\u003cbr>□文博是个赛车手，每天都要骑行训练4个小时，通过训练不断提升体能和技巧。所以对文博来说，骑车是打磨核心技能，每天这4个小时是赚钱时间\u003cbr>□苗苗和辣妹你们计划用一个月骑车走完川藏线，见识沿途的风土人情顺便净化一下心灵。所以骑车对你们来说什么？算是好玩时间\u003cbr>□那你们俩在骑行川藏线的途中碰到了两个熟悉的面孔，原来是楚楚和nancy，她们是两个视频博主，一边骑行一边直播，她们俩是视频博主，正在做骑行到拉萨的直播。那对于她俩来说，骑车所花费的是什么时间？是赚钱时间\u003cbr>□你们告别楚楚和nancy之后继续往前，又遇到正在骑车送快递的春亚，一打听原来川藏线上没有充电站，所以送快递只能靠自行车，那骑车对春亚来说是什么时间啊？又回到生存时间了\u003cbr>□最后，桃子是一个研究员，正在研发一套骑行辅助训练系统帮助文博提高比赛成绩。昨天为了解决一个关键难题他陷入沉思两个钟头，突然灵感迸发找到突破口，这两个小时对桃子来说是什么？是心流时间\u003cbr>\u003cbr>\u003cstrong>【why】\u003c/strong>\u003cbr>所以我们可以看到，因为大家有各自不同的处境，所以花在同一件事儿上的时间对每个人来说意义是不同的。那我们为什么要去关注和分辨时间的类型呢？因为我们每个人所拥有的时间长度都是一样的，人生的差异就来自于时间运用方式的不同，所谓“种瓜得瓜、种豆得豆”。\u003c/p>\u003cp>我们把时间花在了对的方向，那我们的付出才能被称之为奋斗，否则就只是在吃苦。\u003cbr>\u003cbr>\u003cstrong>【how】\u003c/strong>\u003cbr>那具体要怎么分辨呢？通过前面例子我们知道分辨时间类型不能看行为本身，那我们可以从目的和状态这两个方向做判断：\u003cbr>第一.看目的\u003c/p>\u003cp>为了活着，就是生存时间；为了外在形象，就是好看时间；为了休闲消遣，就是好玩时间；为了助益人生目标或价值实现，就是赚钱时间\u003cbr>第二.看状态\u003c/p>\u003cp>在上面分类的基础上再做状态的辨别,做任何一件事的时候如果忘我的沉浸就是心流时间。\u003cbr>\u003cbr>\u003cstrong>【举例说明】\u003c/strong>\u003cbr>比如我今天在这里拆书，大家觉得属于什么时间？\u003c/p>\u003cp>运用我们刚刚的办法：\u003c/p>\u003cp>首先看目的，我们这个拆书和生存有没有关系？当然和生存没有关系，所以不属于生存时间。\u003cbr>那属不属于其他什么时间呢？这就就要看我打算通过拆书实现什么目标了\u003cbr>如果我是希望打磨拆书技能，未来能够成为一个专业培训师或教练，那今天拆书实际上是在打磨和提升自己的核心技能，所以属于赚钱时间\u003cbr>如果是希望以书会友，通过和大家互动增长知识，那今天拆书就属于好玩时间\u003cbr>再看状态，如果我在准备拆书的过程中废寝忘食、流连忘返，或者今天拆过过程中沉浸其中，达到忘我状态，这就属于什么？属于心流时间\u003cbr>\u003c/p>\u003cp>\u003cstrong>【学习者互动】\u003c/strong>\u003c/p>\u003cp>桃子：所以，刚刚问的带娃算什么时间？\u003c/p>\u003cp>回应：好的，回到刚刚nancy的问题，带娃算什么时间？按我们刚刚讲的方法，一看目的二看状态。先看目的，如果你将来期望成为一个育儿方面的专家，你现在通过带娃在做经验积累，那就是赚钱时间。如果你仅仅是带娃，尽管很痛苦但是没办法摆脱于是只好去做，那就是生存时间。再看状态的话，如果你在带娃的过程中沉浸在和娃的互动过程中了，那也可以算心流时间\u003c/p>\u003cp>\u003cbr>\u003cstrong>【预防质疑】\u003c/strong>\u003cbr>好的，我相信大家对几种时间的概念已经清楚了，那你可能会说，我现在知道该怎么分辨我自己的时间了，我也发现我大部分时间都属于生存时间了，可是然后呢？你并没有讲要如何解决这个问题啊，我还是很焦虑啊！那我们说如何解决属于时间规划层面的问题，这属于我们今天要讲的第二个知识点，但是正确的规划是以准确地分类为前提的。所以我们现在所做的，就是在为接下来解决问题打基础。\u003cbr>\u003cbr>\u003cstrong>【where】\u003c/strong>\u003cbr>关于对时间的分类与审视，我们既可以用在工作中，也可以用在生活中。既可以做自我审视，也可以用来帮其他的人做审视。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2 】催化应用\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【显像提问】\u003c/strong>（编写剧本）\u003cbr>我们现在来做一个练习：假设未来某一天你参加同学聚会的时候，发现一个同学有些消沉，他说自己的职业生涯陷入了瓶颈，每天就是周而复始，看不到希望。那你就用今天学到的五种时间的概念帮他做一下时间梳理，让他通过梳理对自己更了解，也开朗了一些。请大家在小组内开展讨论，共同编一个小剧本，剧本需要包括时间、地点、人物，起因、经过、结果和对话等。\u003c/p>\u003cp>我们把今天的伙伴分成两组，nancy左边的小伙伴是第一组，nancy和右边的伙伴是第二组。大家可以先组内思考讨论，然后将剧本摘要写在我提供的模板表格中， 5分钟后我会请小组派代表来分享，现在开始。\u003cbr>\u003c/p>\u003cp>时间到，下面我们邀请第二组的路飞和楚楚来分享你们的剧本，时间2分钟。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003cbr>路飞：时间我们定在了周六晚上10点，地点就在世纪大道的一个大排档，然就我发现楚楚心情不太好，就开始和她聊了\u003c/p>\u003cp>路飞：楚楚，为什么你看上去不开心，好像很抑郁呢？\u003c/p>\u003cp>楚楚：对啊，最近就是觉得上班很迷茫，每天做事也不知道有啥收获，感觉时间就虚度了。然后职业规划也看不到什么希望，就觉得比较迷茫。\u003c/p>\u003cp>路飞：OK，我来帮你分析一下你的时间都用在哪里去了吧，你能告诉我你一天都干了些什么吗？谢谢\u003c/p>\u003cp>楚楚：首先是上班时间。\u003c/p>\u003cp>路飞：上班花了多久？加上路上的时间\u003c/p>\u003cp>楚楚：大概9个小时吧\u003c/p>\u003cp>路飞：还有其他的呢？\u003c/p>\u003cp>楚楚：然后下班了之后回家会遛狗、散步这些\u003c/p>\u003cp>路飞：放松一下，玩一下\u003c/p>\u003cp>楚楚：是的\u003c/p>\u003cp>路飞：你遛狗花了多长时间呢？\u003c/p>\u003cp>楚楚：大概1个小时\u003c/p>\u003cp>路飞：还有其他的吗。比如说上课进修？\u003c/p>\u003cp>楚楚，有时偶尔晚上也会上上课，学习一下，开拓思路，有时也会写一下读书笔记。\u003c/p>\u003cp>路飞：我假设你花在这些事情上的时间是半个小时。那你看你每天上班9个小时再加上吃饭睡觉的时间，这都属于生存时间。遛狗1小时属于好玩时间，学习进修半小时属于赚钱时间，这样一算下来你生存时间的占比太高了，一天中间绝大部分的时间都花在生存时间上了，赚钱时间和好玩时间太少，所以你才会不开心呀。你可以做一些户外运动，或者拆书什么的，或者花些时间打扮一下自己，让时间分配平衡一些。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>第二组的剧本非常好，路飞不仅使用五种时间帮楚楚完成了梳理，还给楚楚提供了建议。感谢二位！\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong> \u003c/p>\u003cp>刚刚我们学习了怎样分辨五种不同的时间，在此基础上我们就可以着手去做一些规划，提高时间的利用效率，接下来我们会学习一种方法叫做时间折叠，它我们今天要学习的第二个知识点。 \u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong> \u003c/p>\u003cp>希望完成第二个知识点的学习之后，我们能（辨析）运用时间折叠法来对工作生活中的的事项进行重组（行为），最终产出一份自己当前的时间规划表（效果）。 \u003c/p>\u003cp>\u003cstrong>【A1自测量表】\u003c/strong> 在开始学习之前，让我们来做个自测。请大家按照提示勾选一下自己的分数，完成之后请把各题的得分累加起来得到一个总分：\u003c/p>\u003cp>\u003cstrong>【解析自测】\u003c/strong>\u003c/p>\u003cp>这个自测表的作用是帮助大家对自己的时间规划意识做一下自我评估，大家可以把自己的总分做一下对照： 18分及以上的同学时间规划意识比较强，今天学到的方法可以丰富你的时间规划工具箱 12分~17分之间的同学具备一定时间规划意识，今天学到的方法可以帮你增强规划能力 12分以下的同学平时可能缺少规划，不妨使用今天学到的方法让自己具备初步的规划能力 下面我们用1分钟来读一下拆页：\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":18493,"quote":"\u003cp>什么是这个时代能够实现的折叠时间呢？可以说，正是信息时代的到来，让我们所有人获得了崭新的时间折叠能力，并在我们还没有深刻认识到折叠时间这个概念的时候，应用在了生活中。\u003cbr>生活和工作中，两种时间的折叠是常见的，我们通常叫作一心二用，一石二鸟，一箭双雕，可以简称为“二折叠”。比如：\u003cbr>· 好看时间+好玩时间：贴着面膜看美剧；\u003cbr>· 生存时间+好看时间：站立办公，或者用带跑步机的办公桌办公；\u003cbr>· 生存时间+好玩时间：上班路上听音频故事；\u003cbr>· 好玩时间+心流时间：用心和孩子一起创造作品；\u003cbr>· 好看时间+赚钱时间：美妆博主直播化妆过程；\u003cbr>· 好玩时间+赚钱时间：游戏玩家比赛；\u003cbr>· 赚钱时间+心流时间：画家完成作品；\u003cbr>· 心流时间+赚钱时间：科学家进行深度研究。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003cbr>这个拆页里有一个新的词汇叫“时间折叠”，所谓时间折叠，就是把多种意义折叠到同一段时间里，说人话就是同时做几件事情。\u003cbr>\u003cbr>\u003cstrong>【why】\u003c/strong>\u003cbr>为什么要做时间折叠呢？因为需要提高时间的利用效率，可是我们每个人的时间总量是恒定的，如果希望时间能具备更丰富的意义，我们就只能努力地去让时间具有更高的折叠率。\u003cbr>\u003cbr>\u003cstrong>【互动提问】\u003c/strong>\u003cbr>下面我们来互动一下，我们说同一个时间做很多事情，不就是一心二用、或一心多用吗？那大家能不能说一个你平时生活中“一心二用”或”一心多用“的例子呢？\u003cbr>\u003c/p>\u003cp>亚茹：我会在跑步的时候，在跑步机上看润总的《进化的力量》视频\u003cbr>回应：很好，你是把好看时间和赚钱时间折叠在了一起\u003cbr>\u003cbr>路飞：我来一个，我会在坐地铁上班的时候听音乐\u003cbr>回应：这个习惯我也有呢，所以你是把生存时间和好玩时间折叠在了一起\u003cbr>\u003c/p>\u003cp>nancy：我还可以同时三个呢？我可以有一边敷面膜，一边开音箱听歌，一边看书。\u003c/p>\u003cp>回应：对的对的，你实现了三重折叠，厉害厉害！\u003c/p>\u003cp>路飞：我有一个问题，你说的时间折叠，指的是我们在同一个时间内做几件不同的事情，还是说做一件事情赋予它不同的意义？\u003c/p>\u003cp>回应：这两种都算时间折叠\u003cbr>\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003cbr>所以我们可以发现时间折叠作为一个方法来说，入门是非常简单的，甚至我们都没学过五种时间但一直在用它。但是当我们把时间折叠这个方法上升到人生规划的高度，我们会发现时间折叠其实是会有策略的，不同的策略会带来不同的结果。所以我们需要根据自己的需求来选择适合自己的折叠策略：\u003c/p>\u003cp>\u003cbr>如果我们追求的是效率，我们可以将生存时间与其他时间折叠在一起，这样可以节省下来更多的时间供自己自由支配\u003cbr>如果我们追求的是价值，我们可以将赚钱时间去与其他时间折叠在一起，这样可以在不经意之间创造财富\u003cbr>如果我们追求的是幸福感，我们可以将心流时间与其他时间的折叠在一起，让人生拥有更好的体验\u003c/p>\u003cp>\u003cbr>\u003cstrong>【举例说明】\u003c/strong>\u003cbr>比如我们上班的途中听音乐，缓解了疲劳，这是生存时间和好玩时间的折叠\u003cbr>比如我们选择站着工作，让自己身材得以保持，这是生存时间和好看时间的折叠\u003cbr>比如美妆博主直播自己化妆的过程，让自己美美的还能赚钱，这是赚钱时间和好看时间的折叠\u003cbr>比如画家沉浸在自己创作的过程中，既享受了幸福感又赚到了钱，这是赚钱时间和心流时间的折叠\u003cbr>\u003cbr>\u003cstrong>【预防质疑】\u003c/strong>\u003cbr>你可能会问，那我只能做两两折叠吗，有没有其他的可能性呢？我们说当然有其他可能性，两两折叠是基础，在特定的场景下我们还可以实现三项、四项时间的折叠，甚至最高的程度可以做到五项折叠在一起。折叠的幅度越大，相当于我们利用同一段时间实现的目标越多，一般能做到五项折叠的都是某个领域的卓越人士。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【where】\u003c/strong>\u003cbr>对于我们一般人来说，在生活中努力做到两项折叠就很不错了\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】\u003c/strong>\u003cbr> 好，下面我们来进行一段现场学习：\u003cbr>\u003cbr>\u003cstrong>【微学习促进】\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>【明确问题】\u003c/strong>\u003cbr> 我们刚刚学到了时间折叠的方法，那么当我们在使用这个方法来做人生规划的时候，会遇到什么困难或障碍呢？给大家5分钟时间讨论一下\u003cbr>\u003c/p>\u003cp>  分组讨论...\u003c/p>\u003cp> 好的，5分钟时间到了，我们请两个小组分别来选择一位代表，分享一下你们的结论，先请第一组：\u003c/p>\u003cp> 安雨：我们觉得有几个可能的困难：一是不确定我想做的事情是否能够带来变现？另一个是执行力方面，虽然我想这么做，但是我不确定能这么做，第三个是时间过于碎片化，导致我没办法去做赚钱的事情所以浪费掉了。\u003c/p>\u003cp> \u003cstrong>拆书家回应：\u003c/strong>\u003c/p>\u003cp> 好的，我们第一组总结出三个困难点，下面有请第二组来分享\u003c/p>\u003cp> 辣妹：我们的第一个困难是，在挖掘心流时间时非常的被动\u003c/p>\u003cp> \u003cstrong>拆书家提问：\u003c/strong>什么叫被动呢？\u003c/p>\u003cp> 辣妹:被动就是太难了，不知道要怎么创造心流时间\u003c/p>\u003cp> 辣妹：第二个是如何在生存时间当中发掘出好玩时间\u003c/p>\u003cp> \u003cstrong>拆书家回应：\u003c/strong>\u003c/p>\u003cp> 好的，我来归纳一下大家的答案。\u003c/p>\u003cp> 第一个是我的努力是否真的能变现？我可能在努力把我的赚钱时间和生存时间折叠在一起，但我不知道我现在努力的对将来有没有用\u003c/p>\u003cp> 第二个是我执行力不足，做不到。\u003c/p>\u003cp> 接下来那个我认为和第二个是同一个问题，为什么呢？因为你说由于时间碎片化而无法有效利用来作为赚钱时间。其实如果你执行力够强，你是可以找到方法去利用这些碎片时间的，正是因为执行力不足，才觉得这是个困难无法克服。\u003c/p>\u003cp> 第三个是不知道怎么创造心流状态\u003c/p>\u003cp> 第四个是不知道怎么在生存时间挖掘出更多好玩时间。\u003c/p>\u003cp> 这四个答案都很好，但是今天我们时间有限，只能选其中一个来探讨和解决，我们现在现场投一下票，大家选哪个来往下探讨和解决呢？\u003c/p>\u003cp> 现场举手投票...\u003c/p>\u003cp> 好的，现在第一个问题的4票，第二个问题0票，第三个问题3票，第四个问题1票，第一个问题得票数最多。\u003c/p>\u003cp> 那我们现在明确了要讨论的问题就是：我怎么知道我现在努力的方向正不正确，是不是能变现？\u003c/p>\u003cp>\u003cstrong>【引导讨论问题的本质】\u003c/strong>\u003cbr>  接下来我们一起来探讨一下造成这个问题的本质原因是什么，是因为什么因素导致了我无法判断我努力的方向正不正确？\u003c/p>\u003cp> 我们还是继续分组讨论，给大家5分钟时间。\u003c/p>\u003cp> 分组讨论...\u003c/p>\u003cp> 好的，5分钟时间到了，我觉得大家讨论得都非常透彻了，我们来听一下两个小组各自的答案，先从第一小组开始：\u003c/p>\u003cp> 苗苗：我们组分析出的本质原因是因为我不知道我的核心能力是什么，所以导致我不知道该往哪个方向去努力\u003c/p>\u003cp> \u003cstrong>拆书家回应\u003c/strong>：\u003c/p>\u003cp> 非常好，本质原因是由于不知道自己的核心能力是什么。我们来听一下第二组的答案\u003c/p>\u003cp> 路飞：我们组觉得是不了解自己，同时也害怕选择\u003c/p>\u003cp>\u003cstrong>【明确问题的本质】\u003c/strong>\u003c/p>\u003cp> 这个答案很有意思，我们来思考一下为什么我们会害怕选择？\u003c/p>\u003cp> 打个比方，如果我们面前有两条路，一条路上堆着金块，走过去就可以拿到，另一条路上什么都没有，那这时我们会不会犹豫要怎么选择，或者害怕选择？当然不会，我们直接往有金块那条路上走就可以了。\u003c/p>\u003cp> 可是如果两条路上什么都看不到，那我们在选择的时候就会犹豫就会害怕了，对吧？\u003c/p>\u003cp> 这里的金块就好比是我们的核心能力，我们害怕选择正是由于我们看不清楚自己的核心能力在哪条路上\u003c/p>\u003cp> 而我们不了解自己指的也是不了解自己的核心能力\u003c/p>\u003cp> 所以呢，第二组的答案可以归集到第一组的答案上，两组达成了一个共识：就是问题的本质是我们不知道自己的核心能力是什么\u003c/p>\u003cp>\u003cstrong>【引导讨论解决方案】\u003c/strong>\u003c/p>\u003cp> 找到了本质问题，我们今天要做一件事情就是打破砂锅问到底，一定要寻找到解决方案。\u003c/p>\u003cp> 那接下来我们再用5分钟时间来分组讨论一下，可以怎么找出自己的核心能力呢？\u003c/p>\u003cp> 分组讨论...\u003c/p>\u003cp> 好的，5分钟时间到了，请问第一组你们找到的方法是什么？\u003c/p>\u003cp> 亚茹：我们小组找到了三个方法：一种说是我们可以去做一些测试，比如像MBTI这样的职业测试，然后对自己有一个了解；然后还有另外一种方法就是多参加一些活动，提高自己的认知；还有一个方法是找人反馈，就比如和自己的朋友或者是前辈了解，听听他们的看法\u003c/p>\u003cp>\u003cstrong> 拆书家回应\u003c/strong>：\u003c/p>\u003cp> 非常好，我归纳一下，第一个方法就是用科学的模型来评估，看看自己属于什么特质，可能适合做什么；第二个是扩大认知范围，全面了解自己，发现自己的潜能；第三个就是广交朋友，当局者迷，但周围的人可以给你客观的建议\u003c/p>\u003cp> 谢谢第一组，下面我们来听听第二组的答案\u003c/p>\u003cp> 路飞：我们组觉得可以从两个方向来看，一个是从自我的方向，我们看自己擅长什么或对什么感兴趣，然后把它发展为核心竞争力。另一个是从市场的方向，我们的什么能力是能被市场认可的，能卖钱的。结合在一起，就是我们的核心能力了。\u003c/p>\u003cp> \u003cstrong>拆书家回应\u003c/strong>\u003c/p>\u003cp> 我们发现，第二组的答案其实是在第一组的基础上做了一个升维，除了从自己内部的角度来找方法，还从外部市场的角度来想问题。真的非常厉害！\u003c/p>\u003cp> \u003cstrong>总结\u003c/strong>\u003c/p>\u003cp> 现在我们总结一下今天微学习的成果。我们今天探讨了在用时间折叠来规划人生的时候可能遇到的困难，一共是四个困难。我们选取其中一个探讨了本质原因，是因为我们不知道自己的核心能力，然后我们一起讨论出了寻找核心能力方法，可以从自身和市场两个角度来思考和尝试。\u003c/p>\u003cp>\u003cstrong> 【A2布置任务】\u003c/strong>\u003c/p>\u003cp> 现在我给大家布置一个课后作业。\u003c/p>\u003cp> 现在我们留一个作业，请大家在下周任选一天，将自己所做的耗时超过1个小时的事情进行记录和归类，并做一下折叠，具体从哪个 \u003cbr>角度都可以，根据你自己的偏好进行。折叠的结果请填在我提供给大家时间折叠表里，完成之后请把你的时间折叠表截图或拍照微信发给我。\u003c/p>\u003cp> \u003cstrong>学员作业反馈\u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong> 时间记录及归类 By 春亚\u003c/p>\u003cp>时间折叠表 By 春亚\u003c/p>\u003cp>时间记录及归类 By 辣妹\u003c/p>\u003cp>时间折叠表 By 辣妹\u003c/p>\u003cp>\u003cbr>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp> 好的，感谢大家今天的参与，今天我们围绕着五种时间的模型学习了两个知识点：\u003c/p>\u003cp> 第一是将时间进行归类，将其分为生存时间、赚钱时间、好看时间、好玩时间和心流时间五种。\u003c/p>\u003cp> 第二是将时间进行折叠，可以是从效率出发将生存时间和其他时间折叠，也可以是从价值角度出发将赚钱时间和其他时间折叠，还可 以从幸福角度出发将心流时间和其他时间折叠。\u003c/p>\u003cp> 希望今天学到的知识能帮助大家合理规划人生，拥抱更好的自己。谢谢！\u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1667529188000,"updated_at":1668521076000,"ria":true},{"id":9099,"topic":"建立你的“验收机制”。","learn_goal":"通过掌握拆解任务、预设标准、逐项验收的方法，让我们做事更高效","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"刘超军","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】时间：30秒 \r\n拆书帮的各位伙伴们大家晚上好！我是刘超军，刘邦的刘，超人的超，军队的军。我用三个标签介绍一下自己：\r\n1、策划人：从事策划工作长达8年\r\n2、管理者：致力于管好自己，管好孩子。\r\n3、进化者：希望有一天我能够进化成“牛人，超人，军人，刘超军”。\r\n预祝大家今晚心情愉快，收获满满！\r\n【引言】时间：30秒\r\n今天我要分享的是书籍叫做《把时间当做朋友》，作者李笑来。李笑来曾经是新东方的讲师，2017年在得到开设专栏《通往财富自由之路》，几个月时间销售额达到恐怖的3700万！\r\n今天我们的学习主题：建立你的验收机制！是书中的一小节。由于篇幅有限，只能抛砖引玉，分享书中一部分内容；如果对这本书感兴趣的话欢迎关注我的下一次分享，我会持续拆解这本书。\r\n好，接下来大家用2分钟时间，仔细阅读我们的拆页：","ratings_count":1,"texts":[{"id":12851,"quote":"\u003cp>【R 阅读原文】2分钟\u003c/p>\u003cp>由此可见，验收机制相当重要。从这个角度讲，我们不管遇到什么任务，都应该对其认真审视，同时向自己提出一个问题并要想办法回答清楚：“怎样才算‘做好’？”如果能（1）把任务拆分成若干个子任务，那么确定“做好”的标准可能更容易一些，因为每个子任务的验收标准可能已经自然存在。\u003c/p>\u003cp>为了能将验收机制落到实处，我们应该在做一件事情之前，（2）拿出纸和笔写下每一个预定的验收标准。经过第2章的讨论，我们已经不会再选择去做那种脆弱而又不现实的“完美主义者”，所以我们也不会设置过高的标准（也就是设置恰当的标准）。走到另一个极端——完全没有标准显然是愚蠢的。（3）而在任务（或子任务）完成时，拿出之前写下的标准对照一下，我们就会发现，这种简单的做法有着不可思议的神奇力量——它会让我们注意更多的细节、进行更多的思考，并不由自主地更为专注。\u003c/p>","explains":"\u003cp>【I 解读】\u003c/p>\u003cp>▲WHAT\u003c/p>\u003cp>OK，大家都读完了。请问大家，什么是“验收机制”呢？\u003c/p>\u003cp>通俗地说，就是对于一个事物，我们要按照一定标准，逐项进行检验而后收下或认可。\u003c/p>\u003cp>比如收快递的时候，我们得看一下是否破损！被盗！货不对板！这就是验收。\u003c/p>\u003cp>▲WHY\u003c/p>\u003cp>为什么需要“验收机制”？\u003c/p>\u003cp>我举个例子，老婆让你去买苹果。如果随便买会怎样？最后老婆会说：价格太贵了吧？买得太多了吃不完，真笨！怎么买个苹果这么久？所以没有验收，很容易【开小差、偏离目标、来回折腾】！\u003c/p>\u003cp>再举个栗子，一个普通人和一个五星级大厨炒菜，味道为什么不一样？因为一个大厨对火候、食材、分量、调料的验收标准都不一样！所以只有按照高标准验收，才能达到专家水平，对吗？\u003c/p>\u003cp>▲HOW\u003c/p>\u003cp>如何建立验收机制？作者提出了“任务验收3步法”：\u003c/p>\u003cp>1、拆解细化。怎么拆解？第一个方法是，把一个任务拆解成多个不同的步骤，比如炒菜要洗，切，炒几个步骤；第二个方法是，拆解成几个不同的维度，比如苹果的价格、大小、颜色。当然不排除还有其他的拆解方法。\u003c/p>\u003cp>2、设置标准。每一个步骤或者维度，都要提前写下清晰的检验标准。\u003c/p>\u003cp>3、逐项验收。任务结束后对照完成标准，盘点收获！\u003c/p>\u003cp>我分享一个自己的实操案例：\u003c/p>\u003cp>任务：1-2拆书重新过级，逐字稿修改\u003c/p>\u003ctable>\u003cthead>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆解\u003c/p>\u003c/td>\u003ctd>\u003cp>标准\u003c/p>\u003c/td>\u003ctd>\u003cp>验收\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1、总部修改意见图片转为文字\u003c/p>\u003c/td>\u003ctd>\u003cp>仔细阅读理解，不得遗漏\u003c/p>\u003c/td>\u003ctd>\u003cp>达成\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、对照总部意见，逐条思考/备注哪些地方需要修改\u003c/p>\u003c/td>\u003ctd>\u003cp>尽量聚焦于具体的案例和应用场景，不要泛泛而谈\u003c/p>\u003c/td>\u003ctd>\u003cp>达成，加入了较多案例\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、用最快的速度完成修改\u003c/p>\u003c/td>\u003ctd>\u003cp>用60分钟完成\u003c/p>\u003c/td>\u003ctd>\u003cp>超时了，实际用时90分钟，对这个任务的难度有所低估！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我发现，当你带着验收标准去完成一个任务，的确会变得更加高效和专注！对自己做得好、做得不好的地方，也可以给自己一个精准的反馈，帮助自己下一次提高！\u003c/p>\u003cp>WHERE\u003c/p>\u003cp>在学习和工作、或者其他目的性很强的活动中，非常适合运用验收机制，敦促自己把细节做好、对结果负责。至于逛街看电影闲聊这种没有明确目的的活动，也许你可以彻底放飞自我，并不需要强制自己去验收。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1 &nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>OK，接下来我们进入A1讨论环节。请问，在最近一周里面，你有没有这样的经历：\u003c/p>\u003cp>为了赶进度闷头往前冲，结果却不理想？\u003c/p>\u003cp>或者做事情丢三落四，导致需要重来？\u003c/p>\u003cp>或者明明付出了努力还被抱怨，有苦劳没有功劳？\u003c/p>\u003cp>（邀请伙伴分享，并给予反馈）\u003c/p>\u003cp>\u003cstrong>小伙伴 殷苗 分享：\u003c/strong>\u003c/p>\u003cp>前两天领导让我负责一份合同的技术部分，让我第二天完成上交，我同意了。结果发现自己对技术这块并不了解！一天过去了还是毫无进展，一脸懵逼！最后不得不跟老板说，一天时间可能不够！\u003c/p>\u003cp>反馈：谢谢殷苗分享的一个经典例子！也许正是因为对技术的不了解、所以导致没有“如何做好合同的验收标准”，耽误了进度，对吗？\u003c/p>\u003cp>\u003cstrong>A2 \u003c/strong>&nbsp;\u003c/p>\u003cp>谢谢你的分享，看来没有验收机制的后果很严重啊。那么接下来做一个练习！\u003c/p>\u003cp>请问在未来的一两周，你是否有想要阅读的书籍？是否有报告方案？有没有其他的学习工作任务？\u003c/p>\u003cp>请你选择一件具体的事情，哪怕是扫地、做饭都可以。然后用验收机制3步法来做一个执行计划，用1分钟时间写下来。\u003c/p>\u003cp>\u003cstrong>小伙伴 馒头 分享读书计划：\u003c/strong>\u003c/p>\u003cp>任务内容： 读一本书\u003c/p>\u003cp>任务目标： 看一小时左右\u003c/p>\u003cp>完成期限： 2天内\u003c/p>\u003ctable>\u003cthead>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>\u003cp>怎么拆解(多个步骤/维度)\u003c/p>\u003c/td>\u003ctd>\u003cp>完成标准是什么\u003c/p>\u003c/td>\u003ctd>\u003cp>验收总结\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1、选书\u003c/p>\u003c/td>\u003ctd>\u003cp>致用类的书\u003c/p>\u003c/td>\u003ctd>\u003cp>/\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、挑最感兴趣的一章\u003c/p>\u003c/td>\u003ctd>\u003cp>选可以解决自己的当前问题的一章\u003c/p>\u003c/td>\u003ctd>\u003cp>/\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、最有感触的地方划重点、写几句感悟\u003c/p>\u003c/td>\u003ctd>\u003cp>至少5-10处感悟，1小时内完成\u003c/p>\u003c/td>\u003ctd>\u003cp>/\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>好，我看到大家写得很不错，拆书结束后大家一定要把这个方法用起来！我的分享结束了！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1571624659000,"updated_at":1571624659000,"ria":true},{"id":8328,"topic":"让节奏慢下来","learn_goal":"提前预测自己需要的技能，并写出具体的安排来习得此项技能","remark":"为什么我们总觉得时间不够用了？为什么我们都有拖延症？为什么速成少见可能？为什么我对现在做的事情会没兴趣？…相信我，你并不孤独，读完这本书，你可以醍醐灌顶地找到答案。","level":"TF2-3","duration":25,"status":29,"type":0,"chaishujia":{"username":"Sophia Ho","city":"佛山"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【\u003cstrong>开场\u003c/strong>】大家好，我是今天过级的拆书家Sophia，我是一位培训人员，心理咨询师与阅读推广者；很开心今天和大家一起分享《把时间当朋友》这本书的部分内容。\u003c/p>\u003cp>【\u003cstrong>分组\u003c/strong>】下面我们先进行分组，我们两人为一组，现场分为3组。\u003c/p>\u003cp>\u003cstrong>【技能点：学习目标】\u003c/strong>\u003cstrong>\u003c/strong>今天我们的学习目标是：大家在跟随我完成本次RIA现场学习后，能够未雨绸缪，提前预测自己需要的技能，并写出具体的实现计划来习得此项技能。\u003c/p>\u003cp>\u003cstrong>【技能点：FAB\u003c/strong>\u003cstrong>图书介绍法】\u003c/strong>\u003c/p>\u003cp>我今天的分享的就是这本书《把时间当作朋友》\u003c/p>\u003cp>\u003cstrong>【F\u003c/strong>\u003cstrong>特征Feature\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>本书作者是李笑来，原来只是本科毕业的新东方老师，然而在时间的积累后，他现在是畅销书的作家和教育咨询合伙人。本书主要内容是介绍如何与时间做朋友，通过累积，通过“心智成长”，成功逆袭的经验与方法。\u003c/p>\u003cp>\u003cstrong>【A\u003c/strong>\u003cstrong>优势Advantage\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>本书有别与市面上时间管理类书籍，它主张我们不要把注意力放在管理“时间”上，因为时间不可管理，时间也不听从任何人的管理，它只会自顾自一如既往地流逝。本书更关注人，也就是主张管理我们“自己”，通过个人独立思考，开启心智，在与时间做朋友的过程中成长自我。\u003c/p>\u003cp>\u003cstrong>【B\u003c/strong>\u003cstrong>利益Benefit\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>平时如果我们总觉得时间不够用了，又感觉自己有有拖延症，临到事情来了才去寻找专家寻求速成方法的话，看完这本说，你不会觉得孤单而且可以找到自己的答案。而我今天分享的片段，大家可以学习到一个方法，应用在生活当中，让自己面对未来不那么的彷徨，可以感觉到时间并没有那么的紧迫，做好相应的技能的储备。\u003c/p>","ratings_count":1,"texts":[{"id":11956,"quote":"\u003cp>今天共拆的是这本书的片段“让节奏慢下来”，现在请大家花1-2分钟时间阅读原文片段。读完时，可以竖起你的大拇指来示意我。谢谢\u003c/p>\u003cp>【主题】让节奏慢下来\u003c/p>\u003cp>【片段来源】拆解片段来自《把时间当做朋友》P303\u003c/p>\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>为什么那么多的人总是幻想有什么“速成”的方法——因为，他们前期松懈了太久，现在突然发现时间不够了，最后期限马上就到了，所以，只有寄希望于“速成”方法的存在。如果你曾经有过类似的幻觉，别奇怪，大多数人都是这样的。这几乎是所有人的本性。而这种本性使得人们不得不最终疲于奔命，于是，速食业也间接因此蓬勃发展；这样的本性还使无数的培训机构构成了一个与所谓正规教育平行的庞大产业；这样的本性使减肥药成为一个庞大的垂直产业——每年全球有上万种新品减肥药上市，无一例外都被证明为无效之后，明年会有更多的同类商品上市，并且会更加热销……\u003c/p>\u003cp>所以，正确的策略应该是：要想办法提前预知自己需要怎样的技能，然后确定那是一个自己可以通过练习真正熟练掌握的技能，而后制定长期计划，一点一点地执行该计划。这根本不是，也不可能是我一个人的独特见解。其实同样的道理已经有很多人给你讲过：“不要等机会来了，才发现自己没有准备好”或者“机会总是眷顾那些准备好了的人”。\u003c/p>\u003cp>懂得这样的道理之后，你就会真正审视生活，然后开始醒悟。其后，你再看看你身边忙忙碌碌却又碌碌无为的人，就知道他们其实有多可笑了，因为他们一生在追求实际上根本得不到的东西，最后只有这样的出路：要么对人生失望，要么选择某个宗教而后寄希望于来世。\u003c/p>","explains":"\u003cp>\u003cstrong>【技能点：把原书的拆页的建议加工出具体步骤】\u003c/strong>\u003c/p>\u003cp>谢谢大家，在本片段里\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>What\u003c/strong>\u003cstrong>】\u003c/strong>作者提出了一个观点：速成绝无可能，这只能是一种幻想。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>Why\u003c/strong>\u003cstrong>】\u003c/strong>我们总在祈求机遇，但是在机遇来的时候往往觉得自己没有准备好。心中总觉“怀才不遇”，却在“遇而不才”上折腰。如果我们对我们的目标没有认知，不懂得为自己储备才能，很有可能与机遇失之交臂或者是在机遇面前病急乱投医，寻求速成，疲于奔命又没实际成果。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>How\u003c/strong>\u003cstrong>】\u003c/strong>那么正确的方法是有远见并做出准备，如何实现？有3个步骤：\u003c/p>\u003cp>1. 定技能：根据自己的目标，提前预知自己需要的技能；\u003c/p>\u003cp>2. 能学习：确定技能是否能通过学习训练就能习得；\u003c/p>\u003cp>3. 做计划：制定长期计划，并拆解成小阶段计划，一步步完成。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>Where\u003c/strong>\u003cstrong>】\u003c/strong>这是一个未雨绸缪的方法，需要我们提前做出预估并付出时间上的学习。它并不适合马上发生或已经发生的事。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>去年4月，工会的Grace请我去主持一场志愿者的晚会。答应时大约有一周的时间。我都跟男主持改稿对练了。晚会前两天，Grace问我是否有主持人闪闪的那种衣服，我囧了，没有！要买已经来不及了，去借没借到。最后穿了我现有的衣服对付过去了。但明显感觉对方是不太满意的。【反思】那时我其实已经上过主持人的课程，就是没有书中所讲的远见来提前学习自己形象管理，以致遇到事情不能应对得体。\u003c/p>\u003cp>\u003cstrong>【加工成正例】\u003c/strong>\u003c/p>\u003cp>当我使用RIA学习了这个片段后，我尝试根据步骤写出自己的计划：1.我的职业目标是成为一名专业培训师，我预知自己需要的技能是声音的运用能力。2.我有上网搜索过资料，也请教过行业中的前辈，他们推荐给我一些这方面的老师，也提点了我一些注意事项。我确认这项技能是可以学会的。3.我计划用未来半年重点练习这个技能，前2个月反复李蕾老师网络课程《练就好声音，让你的话好听、耐听、爱听》；后4个月每周累计3小时进行声音技巧训练。争取在本年内初步习得声音的运用能力。\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp>也许你会说，我也不知道我以后会需要什么技能！是的，没错，也许没有一个人能完全预知自己后面所会的所有技能，但是我可以给些参考给你，比如未婚的朋友，等你以后结婚了，你会需要什么技能？夫妻相处之道？孩子的教育？又或者等我们退休的时候，我们想要有什么兴趣？记录美好生活的摄影？让日子过得更滋润的烹饪？\u003c/p>","interaction":"\u003cp>\u003cstrong>【技能点：案例场景，角色扮演】\u003c/strong>\u003c/p>\u003cp>接下来我给大家设计了一个场景来运用本次拆书的内容，\u003c/p>\u003cp>\u003cstrong>【A3场景假设】\u003c/strong>陆雨本科毕业2年，现在是当地的行政服务中心公职人员，收入还可以，就是她觉得太安逸了，两点一线的生活太平淡，工作总是重复又枯燥，她喜欢烹饪，偶尔在朋友圈晒美食，她马上要跟陈明师姐见面，为她的生活把脉。陈明是小雨的师姐，是一个职业生涯规划师，她将运用本片段中定技能、能学习、做计划这三个步骤为陆雨未雨绸缪。\u003c/p>\u003cp>\u003cstrong>【A3小组讨论】\u003c/strong>现在，请以刚才分好的两人为一组，先进行讨论；然后一位扮演陆雨一位扮演陈明进行演练，时间为6分钟。\u003c/p>\u003cp>\u003cstrong>【A3角色扮演】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>&nbsp;好，时间到了，现在我请这组同学来进行角色扮演，时间4分钟，掌声欢迎~\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>女：最近工作很无聊啊，天天都不知道自己在做什么。\u003c/p>\u003cp>男：我看你朋友圈的奶茶照片挺不错的，可以考虑创业啊。\u003c/p>\u003cp>女：如果是要创业，要学管理还有一些聆听的技巧，还有一些产品的营销手段，都要学一下哦。\u003c/p>\u003cp>男：嗯，对。那你现在的目标是要开一家门店，自己创业，是吧。\u003c/p>\u003cp>女：是的。\u003c/p>\u003cp>男：那你刚才说要学习一些技能，那如何制定一个长期的计划，并把它拆解成一步步去完成呢？\u003c/p>\u003cp>女：你问的非常的具体，我计划一年后开一间奶茶店，我需要先去其他奶茶店去学习一下，在第一线，体会更深，大约是3个月时间；之后要拜师学会配方大约2个月；然后自己也需要学习好管理跟营销的技巧；还要找店铺装修，采购设备定原材料商，差不多一年左右时间完成。\u003c/p>\u003cp>男：听你讲得也挺具体的，预祝你创业成功。\u003c/p>\u003cp>女：谢谢你，到时候请大家喝奶茶。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>谢谢这个小组的分享。非常好。希望我今天带给大家的拆页跟方法，对大家以后的生活是有效的，让大家以后的生活不会那么的忙乱，可以未雨绸缪地过好自己的一声，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1562413783000,"updated_at":1562587609000,"ria":true},{"id":8122,"topic":"建立你的“验收机制”","learn_goal":"全新的任务管理方法，帮你把细节做到完美，积小胜为大胜！","remark":"","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"刘超军","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】时间：30秒 \r\n拆书帮的各位伙伴们大家晚上好！我是刘超军，刘邦的刘，超人的超，军队的军。我用三个标签介绍一下自己：\r\n1、策划人：从事策划工作长达8年\r\n2、管理者：致力于管好自己，管好孩子。\r\n3、进化者：希望有一天我能够进化成“牛人，超人，军人，刘超军”。\r\n预祝大家今晚心情愉快，收获满满！\r\n【学习目标】时间：30秒\r\n今天我要分享的是书籍叫做《把时间当做朋友》，作者李笑来。李笑来曾经是新东方的讲师，2017年在得到开设专栏《通往财富自由之路》，几个月时间销售额达到恐怖的3700万！\r\n今天我们的学习主题：建立你的验收机制！是书中的一小节。由于篇幅有限，只能抛砖引玉，分享书中一部分内容；如果对这本书感兴趣的话欢迎关注我的下一次分享，我会持续拆解这本书。","ratings_count":1,"texts":[{"id":11722,"quote":"\u003cp>好，接下来大家用2分钟时间，仔细阅读我们的拆页：\u003c/p>\u003cp>【R 阅读原文】2分钟\u003c/p>\u003cp>电子游戏的设计者，为游戏者设计了详尽的即时回报系统，包括经验值、等级、宝物等。不仅有正面的回报系统，还有负面的回报系统，如一段时间不登录就会减少经验值等。这种回报系统其实就是设计精良的验收机制。在这种验收机制的“监督”下，每个游戏者都不由自主地“加油干活”，并且乐不思蜀。\u003c/p>\u003cp>有时，我们会发现自己玩某个游戏上瘾了——明知道它占用了很多时间（这是客气的说法，不客气的说法是浪费了很多生命）却忍不住继续……摆脱这种沉迷的方法是找个作弊器。使用作弊器，实际上等同于打破游戏设计者所设计的“验收机制”，使其无效，勾人上瘾的因素也就减轻了。\u003c/p>\u003cp>由此可见，验收机制相当重要。从这个角度讲，我们不管遇到什么任务，都应该对其认真审视，同时向自己提出一个问题并要想办法回答清楚：“怎样才算‘做好’？”如果能（1）把任务拆分成若干个子任务，那么确定“做好”的标准可能更容易一些，因为每个子任务的验收标准可能已经自然存在。\u003c/p>\u003cp>为了能将验收机制落到实处，我们应该在做一件事情之前，（2）拿出纸和笔写下每一个预定的验收标准。经过第2章的讨论，我们已经不会再选择去做那种脆弱而又不现实的“完美主义者”，所以我们也不会设置过高的标准（也就是设置恰当的标准）。走到另一个极端——完全没有标准显然是愚蠢的。（3）而在任务（或子任务）完成时，拿出之前写下的标准对照一下，我们就会发现，这种简单的做法有着不可思议的神奇力量——它会让我们注意更多的细节、进行更多的思考，并不由自主地更为专注。\u003c/p>","explains":"\u003cp>【I 解读】4分钟\u003c/p>\u003cp>▲WHAT\u003c/p>\u003cp>OK，大家都读完了。我们今天的学习主题是验收机制。那什么是“验收机制”呢？\u003c/p>\u003cp>百度百科的定义是：按照一定标准，逐项进行检验而后收下或认可。标准，也就是我们做一件事的时候，所设置的清晰的要求、底线、规范、或者指标。我们可以这样理解验收机制的原理：当一件事的所有细节都达到了标准，才能取得更好的成绩，对吗？\u003c/p>\u003cp>WHY\u003c/p>\u003cp>为什么我们需要“验收机制”？三个理由：\u003c/p>\u003cp>1、没有验收机制，不懂得拆解任务，就容易产生好高骛远的想法。比如很多人一心想发财，想一夜暴富，却不知道从何下手。\u003c/p>\u003cp>2、没有验收机制，没有标准，就等于没有底线、敷衍了事！比如，同样是做清洁，日本清洁之神新津春子可以做到世界第一名；而我们国内很多酒店清洁工却用擦马桶的毛巾擦杯子。\u003c/p>\u003cp>3、没有验收机制，做事之后不做确认和总结，你就不知道自己究竟做好了没有、什么地方还可以提高！\u003c/p>\u003cp>HOW\u003c/p>\u003cp>如何建立验收机制？作者提出了“任务验收3步法”：\u003c/p>\u003cp>1、拆解任务。必须拆解复杂任务，把它细化成若干个简单、具体、可操作的子任务。\u003c/p>\u003cp>2、预设标准。每一个子任务都要提前写下清晰的完成标准，包括期限、数量、质量等指标。\u003c/p>\u003cp>3、逐项验收。对照完成标准，判断成果，盘点收获，反思不足！\u003c/p>\u003cp>举个例子，假如你想要减肥瘦15斤，如何确保自己完成？【打印表格展示】\u003c/p>\u003cp>这里我做了一张减肥计划表：\u003c/p>\u003cp>第一步，把15斤的任务拆分到4个月，然后再把每个月的任务拆分到每天。\u003c/p>\u003cp>第二步，每一天都要有清晰的任务完成标准，包括锻炼、饮食和减重3个指标。\u003c/p>\u003cp>第三步，每天、每月做到了就打勾，总结优点！没做到就要反思不足、尝试弥补！\u003c/p>\u003cp>这样行动，减肥成功的可能性将高得多，对吗？\u003c/p>\u003cp>WHERE\u003c/p>\u003cp>验收机制，适用范围是个人或者团队的任务管理，它不仅能够提升你的做事效率，还能让你越来越自律！但它也有一定的局限性，因为它需要在做事的同时进行记录和反思。而我们执行一些时间紧促、沟通频繁的任务时，往往是不方便记录和停下来思考的。\u003c/p>","interaction":"\u003cp>A1 &nbsp;5分钟\u003c/p>\u003cp>OK，接下来我们进入A1环节，联系自己的过往经验。在讨论开始前，请大家每2个人分为一组，等下大家按照分组进行组内讨论。\u003c/p>\u003cp>我们要讨论的问题是：\u003c/p>\u003cp>请问，在最近1个月内，你是否有计划失败、遭遇挫折的经历？\u003c/p>\u003cp>比方说想带家人外出搞活动，但出了各种纰漏？或者处理一个复杂的工作任务，结果不尽人意？又或者定下了学习计划，却中途夭折？\u003c/p>\u003cp>请大家找到一个这样的案例，并且结合“验收机制”的3个要点进行反思。\u003c/p>\u003cp>（邀请伙伴分享，并给于反馈）\u003c/p>\u003cp>郭妈妈分享：“你讲的这个方法让我收获非常大！我想起我和几个朋友共同成立的婚恋平台，本身资源非常好，但是前期大家一拍即合、没有做好任务细分和标准的确认、更别说“验收”了！现在我们的情况非常尴尬，在（利益分配）一些方面没办法达成一致，平台的发展速度也不如预期。如果能够按照验收机制的方法做好章程和规划，我相信结果会好很多！”\u003c/p>\u003cp>好的，感谢你的分享！其实我们现在亡羊补牢还来得及，对不对？\u003c/p>\u003cp>A2 &nbsp;1分钟\u003c/p>\u003cp>现在我们进入A2环节，规划未来应用！\u003c/p>\u003cp>请问在未来的一两周，你是否有某个外出活动计划？重要工作项目？重大学习目标？\u003c/p>\u003cp>请你用验收机制3步法来做计划，并且用1分钟时间写下来。\u003c/p>\u003cp>好，时间到了！由于时间原因，这个环节就不作分享了，拆书结束后大家可以继续交流！\u003c/p>\u003cp>陈丽青应用计划分享：\u003c/p>\u003cp>“我准备利用“验收机制”三步骤，这样来做归农项目：\u003c/p>\u003cp>当前阶段目标：\u003c/p>\u003cp>6月20日至少完成开V20人升主管\u003c/p>\u003cp>1、拆解任务：\u003c/p>\u003cp>目前完成4人，潜在1人\u003c/p>\u003cp>关键时刻家人补洞2人\u003c/p>\u003cp>还需继续挖掘13人，\u003c/p>\u003cp>距离20号还有15天，\u003c/p>\u003cp>2、预设标准：\u003c/p>\u003cp>每天发3条归农分享朋友圈，\u003c/p>\u003cp>每天主动联系10人，\u003c/p>\u003cp>至少给5人分享归农，\u003c/p>\u003cp>每天主动加好友5人，\u003c/p>\u003cp>每天成交一个新V，\u003c/p>\u003cp>3、逐项验收：\u003c/p>\u003cp>每天午睡和晚睡前检查任务清单\u003c/p>\u003cp>最晚睡觉至少完成验收”\u003c/p>\u003cp>【结语】30秒\u003c/p>\u003cp>最后做一个总结：今天我们学习了一个任务管理的方法，叫验收机制。通过拆解任务、预设标准、逐项验收3个步骤，把每一个子任务都做到完美。细节就是魔鬼，积小胜才能带来大胜！相信这个方法会为你带来惊喜！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1560130972000,"updated_at":1560130972000,"ria":true},{"id":8093,"topic":"有效倾听的3个技巧！","learn_goal":"学会主动帮助说者进入“倾诉”状态！让说话者不吐不快、欲罢不能","remark":"","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"刘超军","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】时间：1分钟\r\n拆书帮的各位伙伴们大家晚上好！我是刘超军，刘邦的刘，超人的超，军队的军。我用三个标签介绍一下自己：\r\n1、策划人：从事策划工作长达8年\r\n2、管理者：致力于管好自己，管好孩子。\r\n3、进化者：希望有一天我能够进化成“牛人，超人，军人，刘超军”。\r\n预祝大家今晚心情愉快，收获满满！\r\n【拆书帮介绍】时间：2分钟\r\n今天有一些新朋友，所以我简单介绍一下咱们拆书帮。\r\n拆书帮是一家公益性的青年成长组织，大家一起互帮互助，学习拆书。非常幸运的是：我们所在的麓山分舵，2018年是全国几十个分舵中培养三级拆书家最多的一个分舵！拆书是什么呢？它一种学习成长的方法论，强调以学习者为中心而不是以知识为中心，从而更好地解决工作生活中的问题！\r\n我们拆书帮运用的读书方法，是拆书帮创始人赵周老师发明的《RIA便签读书法》。什么是RIA？其实它是三个英文单词的缩写。R代表Reading，阅读原文片段。I代表Interpretation，拆书家用自己的语言重述知识点。A代表Appropriation，分为A1联系过去经验划，和A2规划未来应用两个步骤。通过RIA三个便签，可以帮助我们更深入地理解应用书中的知识！\r\n【学习目标】时间：30秒\r\n今天我要分享的是《把时间当做朋友》这本书。与其说它是时间管理，不如说它是一本自我管理的书籍。因为它对于如何管理自己的目标、精力、情绪、人脉都有涉及！\r\n今天我们的学习主题：有效倾听的3个技巧！是书中的一小节。","ratings_count":1,"texts":[{"id":11686,"quote":"\u003cp>【R 阅读原文片段】2分钟\u003c/p>\u003cp>《把时间当做朋友》节选 作者李笑来\u003c/p>\u003cp>一旦决定倾听，就要主动帮助说者进入“倾诉”状态。\u003c/p>\u003cp>在课堂上、会议中，打断说者往往不礼貌且没有必要，甚至会浪费他人的时间、破坏他人的注意力。不过，作为听者，尤其是能被说者看到的听者，给予说者鼓励性的信号会使说者更容易地进入“倾诉”状态。\u003c/p>\u003cp>尽管我个人极端反对欺骗，但是，我发现哪怕遇到不喜欢的说者和内容（人们往往会因为讨厌内容而讨厌说者，或者反过来，因为讨厌说者而讨厌内容），（1）适度控制自己的反感情绪对获取信息也会有极大的正面作用——既然坐在那里，“听而不闻”就是浪费自己的时间。\u003c/p>\u003cp>然而，当面对面交流的时候，（2）听者的反应会在很大程度上影响说者的状态。尽管人们讨厌自己讲话时被打断，但是也没有人喜欢对没有任何反应的听众讲话。从本质上来看，倾诉其实只有两种：第一种是不顾一切地说出来（比如在教堂里隔着纱窗向神父忏悔），第二种是讲给喜欢听的人。所以，给予说者适当的反应，是听者为了有效倾听必须做的事情。\u003c/p>\u003cp>在自己状态不佳、心不在焉的时候，“马上停止谈话”是对双方都有利的事情。一旦听者决定倾听某人的话，就要想办法（3）调动自己的所有感官去感受说者的一切表达方式，包括他的眼神、姿态、动作等，随时随刻尽可能地去想象说者正在经历的情绪状态。一旦听者开始有意识地做这些事，就会不由自主地真正进入“倾听”状态。而后，更为重要的是，由于听者的专注，说者也将不由自主地进入更深的“倾诉”状态。\u003c/p>","explains":"\u003cp>【I 重述原文知识点】4分钟\u003c/p>\u003cp>WHAT 倾听是什么？\u003c/p>\u003cp>这份拆页当中的关键词是倾听。倾听，属于有效沟通的必要部分。倾听的主体是听者，而倾诉的主体是诉说者。两者一唱一和，有排解矛盾或者宣泄感情等优点。\u003c/p>\u003cp>在拆页中，作者提出了一个颠覆我们认知的观点：倾听，仅仅是被动的听就够了吗？远远不够！我们必须要主动地，帮助说话的人进入“倾诉”状态！\u003c/p>\u003cp>WHY：为什么需要倾听力？\u003c/p>\u003cp>在此，我把这种【主动帮助说话的人进入“倾诉”状态】的能力，叫做倾听力。\u003c/p>\u003cp>倾听力是我们工作生活中的重要能力！具备倾听力的人，总能够得到别人的好感、得到更多不为人知的信息。因此，他们往往在人际关系中起到纽带的作用，也更容易成为人群中的意见领袖！对吗？\u003c/p>\u003cp>HOW：提升“倾听力”的3个步骤\u003c/p>\u003cp>那么问题来了——如何提升倾听力？我们需要做到3点。\u003c/p>\u003cp>1、控制情绪。因为表现出反感会导致对方失去讲话的热情，从而失去一些重要的信息。\u003c/p>\u003cp>2、表现兴趣。比如倾听时，我们可以面带微笑，神情专注，和说者进行更多互动。\u003c/p>\u003cp>3、全情投入。努力调动自己的所有感官，去感受说者的一切表达方式，包括他的眼神、姿态、动作等，随时随刻尽可能地想象说者正在经历的情绪状态。\u003c/p>\u003cp>WHERE：\u003c/p>\u003cp>说到这里我要强调：倾听适用于化解矛盾、获取信息、交流感情等沟通场景。但也有例外。第一，你认为不太重要的沟通，可以放弃倾听。否则我们一天什么都做不了，张着耳朵听别人说话就行了。第二，当自己状态不佳时，最好放弃倾听。第三，倾听的技巧也不是只有这3点，也有很多其他的沟通技巧等我们去挖掘，对吗？\u003c/p>","interaction":"\u003cp>【A1 联系过去经验】2分钟\u003c/p>\u003cp>不会倾听，将导致什么后果呢？\u003c/p>\u003cp>接下来分享一个我自己的反面案例：\u003c/p>\u003cp>我家里非常特殊：我的妻子是一个酷爱聊天的人。\u003c/p>\u003cp>她有无数的话题跟我聊，关于工作、生活、家人、关于未来的想象，她最厉害的时候可以从白天聊到晚上，直到我晕过去为止。\u003c/p>\u003cp>但是，上个月有几天我工作忙，心情不好，她聊得不痛快。结果晚上两点钟，她哭着把我从梦中摇醒：“老公，你最近都不听我说话了，你是不是不爱我了？”吓得我屁滚尿流。\u003c/p>\u003cp>现在回想一下，为什么妻子这么大的反应？3个原因。\u003c/p>\u003cp>1、我没有控制情绪。显得有些不耐烦。\u003c/p>\u003cp>2、没有表现出听的兴趣。没有关注妻子说话的内容，没有鼓励她往下说。\u003c/p>\u003cp>3、专注的程度不够。没有认真感受妻子的言行举止，没有感知她心里的苦恼和烦闷。\u003c/p>\u003cp>后来我就长记性了。只要和老婆聊天，即便自己非常不耐烦也要让她说得酣畅淋漓，并且学会了好几个口头禅：哇塞！后来呢？这么厉害？然后呢？\u003c/p>\u003cp>从此以后，我家一片歌舞升平，欣欣向荣。\u003c/p>\u003cp>【A2 规划未来应用】2分钟\u003c/p>\u003cp>1、行动目标：\u003c/p>\u003cp>接下来我们要探讨的问题是：如何应用倾听的3个技巧？\u003c/p>\u003cp>在此分享一个我的个人计划。我的儿子牛牛三岁了，我希望通过倾听和鼓励，让儿子更爱表达！\u003c/p>\u003cp>2、行动计划：\u003c/p>\u003cp>我的计划是：明天下班后，回到家就和儿子“聊天”，鼓励他说一说幼儿园里发生的故事。在过程中做到3点：\u003c/p>\u003cp>1）控制情绪。如果儿子的表达不清晰、也要保持耐心，不急不躁，不要打击儿子的积极性。\u003c/p>\u003cp>2）表现兴趣。对儿子说，“牛牛，今天在学校老师教了你什么呢，爸爸非常想知道哎……”然后儿子每说一句，都夸张的说：“后来发生了什么呢？你真厉害！”\u003c/p>\u003cp>3）全情投入。听儿子讲故事时，自己的语音语调、动作表情可以非常夸张，加入一些表演的元素，和儿子进行互动，让他觉得表达是充满乐趣和成就的事情！\u003c/p>\u003cp>3、奖惩措施：\u003c/p>\u003cp>一个月的训练之后，如果儿子能够完整清晰地讲出在幼儿园发生了什么，我就奖励自己买菠萝蜜吃。否则，一个星期不吃零食！\u003c/p>\u003cp>【结语】30秒\u003c/p>\u003cp>最后大家回忆一下我们今天学到的知识点。倾听的关键在于，帮助说着主动进入轻松的状态。通过控制情绪、表现兴趣、全情投入3个技巧，可以让我们达到更好的倾听效果！希望这次分享对大家有帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1559804719000,"updated_at":1559804719000,"ria":true},{"id":4661,"topic":"正确复述","learn_goal":"让沟通交流过程中的DNA编码正确复制","remark":"","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"姜莹莹","city":"无锡市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"现场的各位小伙伴们,大家晚上好，我叫姜莹莹，大家可以叫我莹莹，今天我给大家分享的是我拆书帮的1-1,我们拆书帮流行应用3个便签介绍自己。今天呢也用三个便签来介绍我自己，爱读书，善于沟通（破冰环节），执行力。爱读书呢，家里有很多书，每天早晨起来或者晚上睡前都会读一个小时的书,如果一天没读书就会感觉少点什么,是典型的认为书中自有黄金屋的人，经常参加各种线下的培训。第二个是善于沟通，可能是从事销售工作原因，能在很短的时间内让对方喜欢我，愿意和我交流，并期待下次和我见面。第三个标签是执行力：我是一个执行力很强的人，在工作中老板安排的工作我都会立即去做，并且想尽各种办法在截止时间之前完成。 （拆书和拆书帮介绍在原文片段前）","ratings_count":1,"texts":[{"id":7703,"quote":"今天呢,我看有很多新来的小伙伴们,那接下来我给大家介绍一下什么是拆书,什么是拆书帮。\r\n什么是拆书：我们从字面上理解拆书是不是把书拆散撕掉，不是的，拆书呢，是把书里的知识转化为自身的能力。方法呢就叫拆书法，拆书法是一种学习的方法，适用于想要提升能力，快速解决具体问题或者说实际问题的成年人，强调的是以学习者为中心，以我们为中心，以人为中心，将知识关联到学习者过去的经验，并帮助其规划未来应用。拆书法分为个人学习法和组织学习法。个人学习的应用是便签法，也就是RIA读书法，阅读，理解，拆为己用。组织学习的应用是拆书家现场引导促进学习者将书中的知识片段理解内化并帮助学习者规划应用。\r\n什么是拆书帮：拆书帮是一群应用拆书法学习的爱好者的社群。表现为全国各地拆书帮分舵，拆书帮的宗旨是帮助更多的学习爱好者成长为拆书家，拆书家相当于学习教练，或者说学习促进者。&nbsp;\r\nR:\r\n那接下来呢，我想给大家3分钟的时间来看一下我今天的拆页，也就是原文片段，大家看完了可以示意我一下：\r\nTF1-1《把时间当作朋友》正确复述\r\n&nbsp;&nbsp;沟通在很多时候并不像看起来那么容易。事实上,在这个过程中,人们常常会因为某个参与者而导致“有效沟通根本不可能达成”。具体一点说,如果甲与乙两个人需要沟通,过程是:甲将他的想法用他的语言表达出来(即)(明编码”),乙用自己的方式去理解甲的语言(即“解码”),然后反过来再次进行。此过程可能重复数次。\r\n发送者→编码→传递→解码→接收者\r\n&nbsp;&nbsp;但是,不同人的“编码/解码”机制常常不相圓。每个人的“编码/解码”机制都是依靠长期积累获得的,而且深受环境的影响。例如,在一些地方,人们们普遍认为“慷慨大方”是褒义词,“精于算计”是贬义词;而在另一些在内通的地方,人们普遍认为“精于算计”才是真本领,“慷慨大方可能往往是智商不够的表现。如果分别来自这两个地方的两个人在相互沟通的过程中没有意识到这样的差异,那么使他们使用的语言相同,沟通的结果也难免扭曲。&nbsp;\r\n&nbsp;&nbsp;&nbsp;况且,发送者生成他的想法——所谓“想明白”本身就不见得是一件容易的事情,“编码/传递/解码”的过程也不一定能够协调无误地实现。再加上即便接收者“解码”正确,他还要把结果与自己的现有知识体系融合,而这也不一定能顺利完成。正确、顺利、有效的沟通到底有多难?这样一说,就很容易理解了。\r\n&nbsp;&nbsp;在这里,我们需要再着重讨论一下“接收者”。假设我们扮演的是沟通中的“接收者”,并且除了我们的“解码”过程外,其他的环节都没有问题。在这种情况下,无论如何我们都可以这样想:我们的“解码”结果不见得正确。所以,为了保证沟通顺利,往往需要添加一个验证机制,或者说反馈机制。\r\n&nbsp;&nbsp;在沟通的过程中,当我们听对方(这里仅限于面对面沟通,不讨论书面沟通)说完之后,应该自觉避免自以为是地认为自己肯定理解对了。我们不妨套用以下句式进行验证、反馈：\r\n“你的意思是…,,…是吗？或者\r\n“你的意思是…我理解得对吗?”\r\n如果对方表示没有问题,就说明讨论可以进行下去;如果对方有异议,就要等待对方的重新表述或者我们的重新理解,直至在这一点上没有异议。当然,这需要耐心,有的时候,甚至是无限的耐心。","explains":"好，我看大部分小伙伴都已经看完了，那这个片段呢是来自李笑来老师的《把时间当作朋友》，下面我想给大家分享一下，我看完这个原文片段，我理解的原文的意思及我过去发生的一个经历和我未来想要通过这个片段的一个应用。\r\nI：\r\n在沟通中，我们有时会理解错对方要传达的意思。即，我们的编码和对方的解码机制是不一样的。比如，“实在”这个词，有些人认为是赞美人忠厚老实的褒义词，有些人认为等同于傻的贬义词。那么如果沟通的两个人对“实在”这个词的理解恰好不一样，恰好又提到这个词的时候，沟通自然也不会顺利进行，甚至会导致双方出现矛盾，比如：不满，争吵。那么为了保证沟通的顺利进行，我们就需要添加一个验证机制，或者说反馈机制。例：在沟通的过程中，当我们听对方说完之后，我们应该给予反馈：“你说的意思是……，是吗？”或者“我理解的意思是……，对吗？”这时对方就会回答对于不对,这样的反馈机制会使编码和解码机制相同，也就是传递者和接收者的理解方式相同，从而保证了正确，顺利，有效的沟通。这个方法适用于当面沟通。","interaction":"接下来我来分享一下我过去发生的一件事情。\r\nA1\r\n前天下午去邻居家玩。夫妻俩男的是东北人女的是江苏人。在聊天的过程中女的说了她老公一个词“你呆啊”然后她老公非常生气，说他老婆怎么可以骂人，结果两个人吵起来了。这个就是典型的两个人因为地域差异理解机制不一样，男的认为呆是傻是笨的意思，女的认为呆带有可爱，萌的意思。当时我想如果她老公知道这个机制，就会问“我理解的呆是傻和笨的意思，你这个呆是什么意思？”对不对吗？然后女的说“不是”我说的意思是你比较可爱，萌的意思。这样两个人就不会吵起来了。\u003cp>A2\u003c/p>\u003cp>看了今天的原文片段呢，我当时想着正好下周一上午9点我要和老板进行一个工作上的沟通，我要向老板汇报近期的工作情况。同时老板也会给我安排接下来的工作任务。在明天和老板的交流过程中，在谈及重要内容和我存在疑意的时候，我要学会复述老板的话，比如“老板，你说的是这个意思对吗？”“您是建议我在放假之前都不要去见王主任，对吗？”这样可以明确老板的想法和意思。也有助于我接下来的工作能顺利达到老板的预期。\u003c/p>\u003cp>以上呢就是我今天的一个分享内容，今天的分享就到这里，谢谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1518244297000,"updated_at":1518245055000,"ria":true},{"id":4371,"topic":"普通人如何加速成长？先学会独立思考！","learn_goal":"如何加速成长？","remark":"每天网上充斥着各种观点，身边的朋友、父母也会给你各种建议，那么到底该听谁的呢？\r\n在面对众多的言论和观点时，我们只有需要学会独立思考，才能判断谁的观点值得自己接受。那么如何才能学会独立思考呢？本周日馒头带你一起学习独立思考，让你的脑子更清楚。","level":"TF3-3","duration":50,"status":30,"type":0,"chaishujia":{"username":"馒头","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是拆书家馒头。目前从事新媒体运营，喜欢阅读、写作和跑步，曾在自媒体平台上写过多篇10万+职场文章，并完成国内最难的金山岭全程马拉松。\r\n近期在专注于独立思考，重新认识生活中的概念。今天要跟大家拆的书籍《把时间当作朋友》是一本关于独立思考难得的好书。\r\n2、图书介绍（1.5min）\r\n【事件】\r\n在找工作时，可能你的父母让你考公务员做一份安稳的工作，身边有的朋友建议你去创业公司可以学到更多东西，还有的朋友建议你去BAT等大公司镀金。感觉每个人都是在为你好，每个人都说的好有道理的样子。\r\n【提问】\r\n那么问题来了，你到底该听谁的建议呢？谁的建议最适合你呢？\r\n【影响】\r\n如果我们自己不会独立思考，只知道盲目听从别人的结论时，那么终究会活成别人眼中的自己，到最后，不仅埋怨别人的建议，还后悔当初为什么不自己做决定。\r\n【解决】\r\n李笑来老师这本《把时间当作朋友》不仅有关于自我管理的方法，还会引导你去进行独立思考。他会帮助你提高独立思考的能力，从而运用心智力量获得更大的成长。","ratings_count":1,"texts":[{"id":7375,"quote":"\u003cp>片段一\u003c/p>\u003cp>片段二\u003c/p>","explains":"\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>拆书片段1（14min）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、学习目标\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够根据独立思考的3个步骤（澄清），判断（行动）别人的结论是否合理（界定），并能够举例说明。\u003c/p>\u003cp>a/对别人的结论保持怀疑\u003c/p>\u003cp>b/重新推演别人给出的结论\u003c/p>\u003cp>b/判断别人的结论是否合理、是否有漏洞\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、R阅读原书拆页（1min）\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读下原文片段，读完的小伙伴请抬头示意我下。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、I讲解引导（3.5min）\u003c/strong>\u003c/p>\u003cp>原文中给我们介绍了独立思考的定义，在作者李笑来看来，独立思考意味着拒绝盲目相信别人的结论，而是要选择自己动脑去重新推演和判断。\u003c/p>\u003cp>独立思考和独自思考是两个不完全相同的概念，独自思考包含独立思考，但是独自思考不等同于独立思考。独自思考强调的你一个人进行思考，思考的内容不受限制。而独立思考，意味着一个人独自思考别人给出的结论是否合理的过程。对思考的内容有明确的要求。比如，参加剽悍一只猫的线上课，如果你一个人完全按照他的方法去思考，这是独自思考。而独立思考，则要求你对他给出的结论进行推演，判断这个结论是否合理，是否有漏洞。\u003c/p>\u003cp>拿我出去骑车旅行问路这件事来说，一开始问路，别人说是哪个方向，我就朝着那个方向骑，结果遇到了断头路。这说明对别人给出的答案，在进行独立思考前，首先要做到保持怀疑，不要盲目相信。\u003c/p>\u003cp>吃过断头路的亏后，下次问路我就不会盲目相信别人的答案，而是会根据地图进行对比和分析，去推演他给出的答案。这就是独立思考的第二步，对别人的答案进行重新推演。\u003c/p>\u003cp>根据地图进行推演后，就能判断别人给出的方向是否跟地图方向一致，如果不一致，我就会反问对方，你自己去过这个地方吗？如果没去过，我就接着再问其他人。这就是独立思考的第三步，判断别人的结论是否合理，是否有漏洞。\u003c/p>\u003cp>【细分步骤】\u003c/p>\u003cp>从刚才列举的例子中，可以发现进行独立思考有3个细分步骤。\u003c/p>\u003cp>a/对别人的结论保持怀疑\u003c/p>\u003cp>b/重新推演别人给出的结论\u003c/p>\u003cp>b/判断别人的结论是否合理、是否有漏洞\u003c/p>\u003cp>从我刚才列举的案例中，可以发现区分信息和知识有明确的先后逻辑顺序，我们需要根据顺序来练习。\u003c/p>\u003cp>如果你不会独立思考，那么很容易迷信权威，被那些所谓的专家给欺骗，轻则损失钱财，重则被洗脑等等。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、A2催化应用（6.5min+3min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面我们进入催化应用环节。\u003c/p>\u003cp>刚刚跟大家分享了如何进行独立思考的3个步骤，帮助我们学会判断别人的结论。\u003c/p>\u003cp>为了帮助大家更好地学会独立思考，接下来在请大家编一个剧本。当你身边的小伙伴，\u003c/p>\u003cp>因为不知道独立思考，喜欢迷信专家，你会如何运用今天学习的3个步骤，去帮他进行独立思考，判断专家的结论是否合理、是否有漏洞呢？\u003c/p>\u003cp>要有具体的时间，地点，人物，起因经过结果的小故事，并且要有对话，给大家6分钟的时间讨论。3个人为一组，其中1个小伙伴是当事人，1个小伙伴为咨询师运用今天学习的内容给他出谋划策，另1位小伙伴监督这个故事是否包含时间、地点、人物起因经过结果和对话。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>悠兰和ava分别扮演大学同学，地点在大学寝室，讨论内容为毕业找工作。\u003c/p>\u003cp>ava：一个礼拜没见，你工作找的怎么样？\u003c/p>\u003cp>悠兰：你看我这样子，简历准备了好几份，现在不知道是投哪家公司。\u003c/p>\u003cp>ava：你现在掌握了哪些信息呢？\u003c/p>\u003cp>悠兰：我之前一直在互联网公司实习，想找互联网公司的工作。想过去今日头条、爱奇艺等等。但是我在知乎上看到一个大牛的帖子，发现帖子上一点资讯和爱奇艺的工资给的还不错。\u003c/p>\u003cp>ava：那个大牛是什么背景，他为什么会有这个数据呢？\u003c/p>\u003cp>悠兰：但是这个帖子有很多人跟帖\u003c/p>\u003cp>ava：这些跟帖的人是怎样评论的呢？\u003c/p>\u003cp>悠兰：各种评论都有，说腾讯给了多少K，百度给了多少K等等，大家各种都在说。\u003c/p>\u003cp>ava：大家说的是验证了他这个帖子的科学性，但是你是否知道，通常工资待遇是保密的，你再想想，先保持怀疑的态度，可以在验证下。另外你说到今日头条工资非常高，高到什么程度呢？\u003c/p>\u003cp>悠兰：我不知道这个工资是怎么来的，具体数额是35K*16，我觉得不太可能，可能是技术类的待遇。\u003c/p>\u003cp>ava：我觉得头条是资讯类APP，那么你有了解同行公司待遇吗？比如说一点资讯。\u003c/p>\u003cp>悠兰：一点资讯待遇不到今日头条的一半\u003c/p>\u003cp>ava：那么你觉得同行业之间，待遇相差这么大合理吗？\u003c/p>\u003cp>悠兰：不合理，我需要进一步验证。\u003c/p>\u003cp>【给予分享者反馈】\u003c/p>\u003cp>刚才教练通过提问的方式，去引导当事人进行怀疑、推演，去判断大牛给的薪资结论是否正确，结果发现两家同行业公司，薪资相差好几倍，发现了不合理地方，需要进一步确认。感谢小伙伴的分享，当你开始独立思考时，才会发现很多人的结论并不可靠。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>独立思考让我们勤于思考，但是如何才能清晰的思考呢？这就需要我们脑子清楚。\u003c/p>","interaction":"\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>拆书片段2（36min）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够根据原文，准确区分脑子清楚和脑子明白的差别，并在现场学习中讨论出如何正确区分概念的步骤。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、A1请大家自测（2min）\u003c/strong>\u003c/p>\u003cp>请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分。（1表示很不符合，5表示非常符合）\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我总是混肴不同事物的概念。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、学习任何知识，我总是忽略基础概念的学习。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我看问题，总是看到表面，很难透过现象看本质。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我从来没有过深度思考1小时的经历。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我很少对自己的认知进行反思和修正。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、I解释自测题（1.5min）\u003c/strong>\u003c/p>\u003cp>得分在5-25分之间，得分越高，说明你区分概念的能力越弱。得分越低，说明你区分概念的能力越强。20-25分的小伙伴，说明区分概念的能力很弱；10-20分的小伙伴，说明区分概念的能力一般；10分以下的小伙伴，说明区分概念的能力很强。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、R阅读原书拆页（1min）\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读下原文片段，读完的小伙伴请抬头示意我下。\u003c/p>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>、I讲解引导（7min）\u003c/strong>\u003c/p>\u003cp>【学习者互动】\u003c/p>\u003cp>我先来解释下概念，概念是指从感性认识上升到理性认识，把所感知的事物的共同本质特点抽象出来，加以概括。那么原文中“脑子清楚“的概念跟你平常理解的一样吗？\u003c/p>\u003cp>(不一样)\u003c/p>\u003cp>【概念对比】\u003c/p>\u003cp>对的，原文中的脑子清楚，指的是我们脑子里没有混肴视听、错误的概念，能够清楚的知道生活及工作中的很多概念是什么样子。它跟我们经常说的脑子明白是两个不同的概念，脑子明白通常是指你知道了某件事物或者了解某件事物，并不全是指的概念。而这里的脑子清楚是针对我们对概念的正确理解。\u003c/p>\u003cp>【学习者互动】（1min）\u003c/p>\u003cp>请问大家知道知识的概念吗？\u003c/p>\u003cp>邀请知道的小伙伴回答，然后分享自己的案例。我自己曾经就因为不清楚知识的概念，结果让自己知道很多信息，但是却没有掌握足够的知识。没加入拆书帮之前，我看书都是不做笔记，不画线，只图快速看完。看完后还会窃窃自喜，自己又看完了一本书，学到了很多知识。我把知识错误的理解为了信息，结果没有拆为己用。后来在成甲《好好学习》书中，才清楚的知道知识并不是信息，只有能够改变自己的行动的信息才能被称为知识。\u003c/p>\u003cp>【WHY】（3min）\u003c/p>\u003cp>提问学习者：做一个脑子清楚的人，搞清楚概念有什么好处？\u003cbr> 学习者李斌分享：我在华为公司工作，公司有上万人，如果概念不清楚，那么沟通起来非常费劲，你需要不断去解释这个概念是什么意思。当大家都能搞清楚概念，才会不引起误解和异议。\u003c/p>\u003cp>学习者熊分享：我是觉得像现在网红、知识IP和斜杠青年，如果能够搞清楚概念，那么就能快速知道这些新名词是什么概念。也就是说搞清楚概念能够提高认知效率。\u003c/p>\u003cp>学习者追逐分享：理解概念是第一步，必须要了解概念的内涵，比如拆书A1+、A2等的概念。也就是说，搞清楚概念是行动的第一步。\u003c/p>\u003cp>（思考决定行动。脑子清楚了，才会有正确的行动。如果脑子不清楚，那么你很容易跑偏或者跑错路。改变自己，需要先从改变脑子开始。）\u003c/p>\u003cp>\u003cstrong>6\u003c/strong>\u003cstrong>、A3促动参与（23min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>A1：你有过搞清楚一个概念的经历吗？请举例说明（2min）\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者李斌分享：读书和拆书过程中，就能帮助自己搞清楚概念。自己理解清楚拆书中A1+的概念。斌哥第一次拆2-1时，因为不清楚A1+的概念，结果导致2-1挂了。搞清楚在拆书练级过程中，也是十分重要的。\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>对学习者李斌进一步提问：（5min）\u003c/p>\u003cp>1、 可以具体解释下A1+是什么意思吗？\u003c/p>\u003cp>李斌：A1+是指针对过去做的不够好的案例，以后在遇到，该如何运用原文中知识点进行解决。\u003c/p>\u003cp>2、 请问是什么时候弄清楚这个概念的？\u003c/p>\u003cp>李斌：2-1挂掉的时候，才弄清楚A1+的概念\u003c/p>\u003cp>3、 当时是如何弄清楚这个概念的？\u003c/p>\u003cp>李斌：自己先通过A1+和A2进行对比，有了初步的理解，然后再询问二毛师兄，获得更深的理解。\u003c/p>\u003cp>4、 你觉得弄清楚这个概念难在哪里？\u003c/p>\u003cp>李斌：主要难在自己将A1+和A2容易混肴，需要正确区分A1+和A2的概念，才能真正理解清楚A1+的概念。A2跟A1+是两个不完全相同的概念，A1+和A2，虽然都是对原文知识点的规划运用，但是A1+明确是对过去失败例子如何在未来进行纠正。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者悠兰分享：很多时候，其实你以为自己搞清楚了，但实际没有搞清楚。电影制作的出品和发行是两个相似的概念，最开始我就把这两个概念搞混肴，结果导致自己在工作犯错。其实出品和发行是两个不同的概念，如果不会正确区分相似概念，就很难理解清楚。\u003c/p>\u003cp>\u003cstrong>把概念搞清楚到底难在哪里？（明确问题）\u003c/strong>刚刚两位学习者的分享，都提到弄清楚概念的难点在于正确区分概念。那么弄清楚概念都是难在这正确区分概念吗？接下来，我们分组讨论（3min）。\u003c/p>\u003cp>学习者悠兰：当我们学习一个概念后，以为自己理解清楚了，但其实并没有搞清楚。因为下次遇到相似的概念，我们就会理解错误，或者将相似的概念和正确概念理解为一回事。当学会正确区分概念，才能说明你是真正搞清楚了这个概念。\u003c/p>\u003cp>学习者ava：如果不知道区分概念，那就不能说明搞清楚概念了。当你能够准确区分两个相似的概念，才能说明你是抓住这个概念的本质。\u003c/p>\u003cp>我们再回顾下之前做的自测题，从自测题的得分，也能看出来，因为区分概念能力弱，才会导致我们对概念理解不清楚。\u003c/p>\u003cp>（\u003cstrong>明确问题的本质：学会正确区分概念，才能搞清楚概念\u003c/strong>）\u003c/p>\u003cp>【现场讨论解决方案】\u003c/p>\u003cp>弄清楚概念的本质是学会正确区分概念，那么如何才能正确区分概念呢？\u003c/p>\u003cp>接下来我想请现场的小伙伴结合刚才我们列举出的概念，一起讨论下，如何才能正确区分概念呢？有哪些方式？需要哪些步骤？请把你们讨论出来的可行做法记录在一张白纸上，5分钟后，我请每组派代表来讲解你们的成果。（15分钟）\u003c/p>\u003cp>学习者追逐分享：正确区分概念的方法有4个。一是询问对这个概念理解清楚的专家或有经验的人；二是上网查找概念相关的资料，进行对比分析；三是找权威经典的书籍，进一步理解概念；四是跟身边的学习者一起探讨，相互提问。\u003c/p>\u003cp>学习者董军分享：首先要定义清楚，其次是追根溯源，找到这个概念的出处和源头。你要找到这个概念是在什么情况下定义的有哪些适用范围和边界条件。\u003c/p>\u003cp>具体步骤：\u003c/p>\u003cp>1、 通过查找资料，追根溯源了解概念的出处\u003c/p>\u003cp>2、 对相似概念进行对比，分析相同点和不同点\u003c/p>\u003cp>3、 实践运用概念，进一步反思和琢磨\u003c/p>\u003cp>\u003cstrong>7\u003c/strong>\u003cstrong>、A2催化应用（1.5min）\u003c/strong>\u003c/p>\u003cp>【特定任务的A2】\u003c/p>\u003cp>今天跟大家分享了如何学会正确区分概念，让脑子更清楚。学是为了更好的用，晚上大家回到家后，请根据找到正确区分概念的方法和步骤，去搞清楚1个概念。 个人微信号：mantoupaojiao。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者悠兰根据正确区分概念的3个步骤，区分喜欢、爱情、好感，理解爱情这个概念本质的含义。通过查找字典，发现喜欢、好感是一种态度和感觉，而爱情则是一份感情。真正的爱情包括爱的感觉和陪伴的感情。如果你暗恋一个人，那是只有感觉的残缺的爱情。如果你们相敬如宾的走到了一起，那时只有感情的残缺的爱情。运用这个概念分析文章、马伊琍事件，文章和马伊琍之间只有陪伴的感情，缺少爱的感觉。\u003c/p>\u003cp>\u003cstrong>五、结语（1min）\u003c/strong>\u003c/p>\u003cp>学会独立思考，搞清楚概念，才能让自己脑子更清楚，活的更明白。希望今天分享的独立思考和区分概念能够帮助你获得更好的成长，我是今天的拆书家馒头，谢谢大家的聆听和陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514898655000,"updated_at":1514898655000,"ria":true},{"id":4370,"topic":"如何做出短期有效的计划？","learn_goal":"学会制定一个月短期计划，并确保计划现实可行","remark":"在生活中是否常常想学习一种技能却不知道如何做计划，或者做了长长的计划却没有实现，其实，要制定一个月的计划，需要在制定计划的时，想想这目标是否现实可行，如果目标是对的话，要考虑自己是否能够坚持长期计划，在制定计划的时候，要考虑到自己的情况，根据自身的情况分析自己究竟适合什么样的计划。那么快来现场体验如何做短期有效可执行的计划吧！","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"方凯","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"各位伙伴们，大家好，我叫方凯。大家可以叫我小方，现在我是一名准医生，在医院开始我的实习生涯，我的三个标签：准医生，志愿者，拆书小白，准医生是自己对自己的大学生涯的总结；志愿者是自己在大学时光中一直扮演的角色，也是以后自己想要成为的人；拆书小白是自己现阶段的状态。通过这三个标签来提醒自己现在和未来将要做的事情，让自己成为更好的人。我的爱好广泛，平时读读书、打打球、跑跑步。喜欢交友，我的理想状态是：有三两好友，拼搏奋斗。一生足以。现目前最大的愿望是在不久的将来通过自己的努力成为一名三级拆书家。","ratings_count":0,"texts":[{"id":7374,"quote":"\u003cp>计划成功的前提：目标现实可行。我们不是计划着去失败，而是失败的计划。如果一个人的目标是制作永动机或者炼制长生不老丹，那么无论他怎样坚持不懈，理论上都是没有意义的，因为这样的目标不现实。\u003c/p>\u003cp>制定短期计划。因为长期计划是需要通过实践才能习得的能力，如果计划过于长远，我们发现计划总是被变化打乱，有人说,计划总是没有变化快，事实上，无论变化多快，计划总是要有的，只是在制定计划的时候，应该考虑到变化，应该以自身的情况分析自己究竟适合制定多久的计划。\u003c/p>\u003cp>初始状态下，对任务连基本的认知都没有的时候，我们往往没有能力去制定合理有效的计划。在大多数情况下，我的建议是这样的：先制定出一个你认为可行的短期计划，然后去做就是了，不要怕失败，每次受到挫折之后要吸取教训，根据自身情况自我调整，你就会制定出适合自己的计划。\u003c/p>\u003cp>在目标现实可行、方向确定的情况下，才能成功。一般来讲，限期越短、内容越清晰，目标就越容易实现。\u003c/p>\u003cp>计划固然重要，行动更为重要。\u003c/p>","explains":"\u003cp>图书介绍：我今天将要讲的书籍名叫把时间当做朋友——作者是李笑来，这本书从心智成长的角度来谈时间管理，指出时间管理是成功的关键所在。作者引述自己从事的职业中所遇到的事例，告诉我们：如何打开心智，如何运用心智来和时间做朋友，如何理解时间管理的意义，在时间管理上取得突破，进而用心智开启自己的人生成功之旅。\u003c/p>\u003cp>片段介绍：各位小伙伴是否经常列了一大堆的计划没有完成，或者看着计划却不知道怎么做，今天我为大家拆解的片段就是如何做计划。\u003c/p>\u003cp>分组：为了更好的学习本片段，要对大家分个组，闲话不多说，马上开始正文的阅读，请大家花两分钟的时间阅读本章节，读完的小伙伴举手示意下我\u003c/p>\u003cp>［I］拆书家讲解引导 &nbsp;相信各位小伙伴都看完原文片段了，那接下来我就谈谈我对原文片段的理解。在制定计划的时候，要想想这目标是否现实可行，如果目标是对的话，要考虑自己是否能够坚持长期计划，在制定计划的时候，要考虑到自己的情况，根据自身的情况分析自己究竟适合什么样的计划，对于一些写了长期计划而没有实现目标的小伙伴，原文提出了一种思路：首先先确保你的目标现实可行，在结合你自身的情况制定出一个你认为可行的短期计划，然后根据计划去行动。在行动过程中有问题随时调整计划。我举个自己的例子，我在17年有个梦想，减重20公斤。在年初的时候我制定了一年的计划，在最开始的一星期内我信心满满地每天按照计划做，过了一周后懒惰开始了，只是象征性地完成计划，到最后什么也不做了，我觉得这样下去不行，我下载了fit这个软件，软件为我制定了一个月计划，我跟着练习了一个月。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：17年即将过去了，18年即将到来，各位还记得自己在17年许下的愿望吗？到现在实现了吗？请各位小伙伴在小组内分享下自己曾经做过的计划以及自己的行动。正面的反面的都可以。要求：要有具体的时间、地点、人物和事件。限时3分钟。\u003c/p>\u003cp>拆书家设计提问：听到各位小伙伴的精彩分享，发现我们在制定计划上有这么多问题，那今天通过学习这个片段之后呢？我们应该怎么去做？接下来我们进行最后的环节---拆为己用。18年即将到来，各位小伙伴肯定心中有很多梦想等待实现。接下来请各位小伙伴写下对于某个目标的一个短期计划。注意要有具体的时间节点，人物。事件。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514897575000,"updated_at":1514897575000,"ria":true},{"id":4368,"topic":"学习独立思考，让你的脑子更清楚","learn_goal":"学习独立思考，让你的脑子更清楚","remark":"每天网上充斥着各种观点，身边的朋友、父母也会给你各种建议，那么到底该听谁的呢？\r\n在面对众多的言论和观点时，我们只有需要学会独立思考，才能判断谁的观点值得自己接受。那么如何才能学会独立思考呢？本周日馒头带你一起学习独立思考，让你的脑子更清楚。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"馒头","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是拆书家馒头。目前从事新媒体运营，喜欢阅读、写作和跑步，曾在自媒体平台上写过多篇10万+职场文章，并完成国内最难的金山岭全程马拉松。\r\n近期在专注于独立思考，重新认识生活中的概念。今天要跟大家拆的书籍《把时间当作朋友》是一本关于独立思考难得的好书。\r\n2、图书介绍（1.5min）\r\n【事件】\r\n在找工作时，可能你的父母让你考公务员做一份安稳的工作，身边有的朋友建议你去创业公司可以学到更多东西，还有的朋友建议你去BAT等大公司镀金。感觉每个人都是在为你好，每个人都说的好有道理的样子。\r\n【提问】\r\n那么问题来了，你到底该听谁的建议呢？谁的建议最适合你呢？\r\n【影响】\r\n如果我们自己不会独立思考，只知道盲目听从别人的结论时，那么终究会活成别人眼中的自己，到最后，不仅埋怨别人的建议，还后悔当初为什么不自己做决定。\r\n【解决】\r\n李笑来老师这本《把时间当作朋友》不仅有关于自我管理的方法，还会引导你去进行独立思考。他会帮助你提高独立思考的能力，从而运用心智力量获得更大的成长。","ratings_count":0,"texts":[{"id":7371,"quote":"\u003cp>片段一\u003cbr>\u003c/p>\u003cp>片段二\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够根据独立思考的3个步骤（澄清），判断（行动）别人的结论是否合理（界定），并能够举例说明。\u003c/p>\u003cp>a/对别人的结论保持怀疑\u003c/p>\u003cp>b/重新推演别人给出的结论\u003c/p>\u003cp>b/判断别人的结论是否合理、是否有漏洞\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、R阅读原书拆页（1min）\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读下原文片段，读完的小伙伴请抬头示意我下。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、I讲解引导（3.5min）\u003c/strong>\u003c/p>\u003cp>原文中给我们介绍了独立思考的定义，在作者李笑来看来，独立思考意味着拒绝盲目相信别人的结论，而是要选择自己动脑去重新推演和判断。\u003c/p>\u003cp>独立思考和独自思考是两个不完全相同的概念，独自思考包含独立思考，但是独自思考不等同于独立思考。独自思考强调的你一个人进行思考，思考的内容不受限制。而独立思考，意味着一个人独自思考别人给出的结论是否合理的过程。对思考的内容有明确的要求。比如，参加剽悍一只猫的线上课，如果你一个人完全按照他的方法去思考，这是独自思考。而独立思考，则要求你对他给出的结论进行推演，判断这个结论是否合理，是否有漏洞。\u003c/p>\u003cp>拿我出去骑车旅行问路这件事来说，一开始问路，别人说是哪个方向，我就朝着那个方向骑，结果遇到了断头路。这说明对别人给出的答案，在进行独立思考前，首先要做到保持怀疑，不要盲目相信。\u003c/p>\u003cp>吃过断头路的亏后，下次问路我就不会盲目相信别人的答案，而是会根据地图进行对比和分析，去推演他给出的答案。这就是独立思考的第二步，对别人的答案进行重新推演。\u003c/p>\u003cp>根据地图进行推演后，就能判断别人给出的方向是否跟地图方向一致，如果不一致，我就会反问对方，你自己去过这个地方吗？如果没去过，我就接着再问其他人。这就是独立思考的第三步，判断别人的结论是否合理，是否有漏洞。\u003c/p>\u003cp>【细分步骤】\u003c/p>\u003cp>从刚才列举的例子中，可以发现进行独立思考有3个细分步骤。\u003c/p>\u003cp>a/对别人的结论保持怀疑\u003c/p>\u003cp>b/重新推演别人给出的结论\u003c/p>\u003cp>b/判断别人的结论是否合理、是否有漏洞\u003c/p>\u003cp>从我刚才列举的案例中，可以发现区分信息和知识有明确的先后逻辑顺序，我们需要根据顺序来练习。\u003c/p>\u003cp>如果你不会独立思考，那么很容易迷信权威，被那些所谓的专家给欺骗，轻则损失钱财，重则被洗脑等等。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、A2催化应用（6.5min+3min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面我们进入催化应用环节。\u003c/p>\u003cp>刚刚跟大家分享了如何进行独立思考的3个步骤，帮助我们学会判断别人的结论。\u003c/p>\u003cp>为了帮助大家更好地学会独立思考，接下来在请大家编一个剧本。当你身边的小伙伴，\u003c/p>\u003cp>因为不知道独立思考，喜欢迷信专家，你会如何运用今天学习的3个步骤，去帮他进行独立思考，判断专家的结论是否合理、是否有漏洞呢？\u003c/p>\u003cp>要有具体的时间，地点，人物，起因经过结果的小故事，并且要有对话，给大家6分钟的时间讨论。3个人为一组，其中1个小伙伴是当事人，1个小伙伴为咨询师运用今天学习的内容给他出谋划策，另1位小伙伴监督这个故事是否包含时间、地点、人物起因经过结果和对话。\u003c/p>\u003cp>【给予分享者反馈】\u003c/p>\u003cp>感谢小伙伴的分享，当你开始独立思考时，才会发现很多人的结论并不可靠。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>独立思考让我们勤于思考，但是如何才能清晰的思考呢？这就需要我们脑子清楚。\u003c/p>","interaction":"\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>拆书片段2（36min）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者能够根据原文，准确区分脑子清楚和脑子明白的差别，并在现场学习中讨论出如何正确区分概念的步骤。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、A1请大家自测（2min）\u003c/strong>\u003c/p>\u003cp>请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分。（1表示很不符合，5表示非常符合）\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我总是混肴不同事物的概念。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、学习任何知识，我总是忽略基础概念的学习。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我看问题，总是看到表面，很难透过现象看本质。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我从来没有过深度思考1小时的经历。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我很少对自己的认知进行反思和修正。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、I解释自测题（1.5min）\u003c/strong>\u003c/p>\u003cp>得分在5-25分之间，得分越高，说明你区分概念的能力越弱。得分越低，说明你区分概念的能力越强。20-25分的小伙伴，说明区分概念的能力很弱；10-20分的小伙伴，说明区分概念的能力一般；10分以下的小伙伴，说明区分概念的能力很强。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、R阅读原书拆页（1min）\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读下原文片段，读完的小伙伴请抬头示意我下。\u003c/p>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>、I讲解引导（7min）\u003c/strong>\u003c/p>\u003cp>【学习者互动】\u003c/p>\u003cp>原文中“脑子清楚“的概念跟你平常理解的一样吗？\u003c/p>\u003cp>(不一样)\u003c/p>\u003cp>【概念对比】\u003c/p>\u003cp>对的，原文中的脑子清楚，指的是我们脑子里没有混肴视听、错误的概念，能够清楚的知道生活及工作中的很多概念是什么样子。它跟我们经常说的脑子明白是两个不同的概念，脑子明白通常是指你知道了某件事物或者了解某件事物，并不全是指的概念。而这里的脑子清楚是针对我们对概念的正确理解。\u003c/p>\u003cp>【学习者互动】（1min）\u003c/p>\u003cp>请问大家知道知识的概念吗？\u003c/p>\u003cp>邀请知道的小伙伴回答，然后分享自己的案例。我自己曾经就因为不清楚知识的概念，结果让自己知道很多信息，但是却没有掌握足够的知识。没加入拆书帮之前，我看书都是不做笔记，不画线，只图快速看完。看完后还会窃窃自喜，自己又看完了一本书，学到了很多知识。我把知识错误的理解为了信息，结果没有拆为己用。后来在成甲《好好学习》书中，才清楚的知道知识并不是信息，只有能够改变自己的行动的信息才能被称为知识。\u003c/p>\u003cp>【学习者互动】（1min）\u003c/p>\u003cp>请问大家知道财务自由的概念吗？\u003c/p>\u003cp>邀请小伙伴回答，然后分享自己的案例。以前我以为赚很多钱，就能达到财务自由。但后来发现，赚的多，花的越多。那些中了500万彩票的人，大部分都变成了穷光蛋。最后在李笑来《财富自由之路专栏》里才明确的知道，原来财富自由是指你不必为了生活必需而出售自己的时间。也就是说，你的被动收入能够支付你的日常开支。\u003c/p>\u003cp>【WHY】（1min）\u003c/p>\u003cp>提问学习者：我们为什么要做一个脑子清楚的人呢？\u003c/p>\u003cp>（思考决定行动。脑子清楚了，才会有正确的行动。如果脑子不清楚，那么你很容易跑偏或者跑错路。改变自己，需要先从改变脑子开始。）\u003c/p>\u003cp>\u003cstrong>6\u003c/strong>\u003cstrong>、A3促动参与（23min）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>A1：生活中，你脑子里有哪些重要清楚的概念呢？请举例说明（2min）\u003c/p>\u003cp>（资本、时间管理、目标、计划等）\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>对学习者进行追问：（3min）\u003c/p>\u003cp>1、 这个概念可以具体解释下是什么意思吗？\u003c/p>\u003cp>2、 请问是什么时候弄清楚这个概念的？\u003c/p>\u003cp>3、 当时是如何弄清楚这个概念的？\u003c/p>\u003cp>4、 你觉得弄清楚这个概念难在哪里？\u003c/p>\u003cp>5、 所有的概念都是难在这里吗？\u003c/p>\u003cp>我们接下来分组讨论下，把概念搞清楚到底难在哪里？（明确问题）（5min）\u003c/p>\u003cp>学会正确区分概念（明确问题本质）（2min）\u003c/p>\u003cp>【现场讨论解决方案】\u003c/p>\u003cp>弄清楚概念的本质是学会正确区分概念，那么如何才能正确区分概念呢？\u003c/p>\u003cp>接下来我想请现场的小伙伴结合刚才我们列举出的概念，一起讨论下，如何才能正确区分概念呢？有哪些方式？需要哪些步骤？请把你们讨论出来的可行做法记录在一张白纸上，5分钟后，我请每组派代表来讲解你们的成果。（讨论时间5分钟+分享时间3分钟+整理行动步骤3分钟，总共11分钟）\u003c/p>\u003cp>\u003cstrong>7\u003c/strong>\u003cstrong>、A2催化应用（1.5min）\u003c/strong>\u003c/p>\u003cp>【特定任务的A2】\u003c/p>\u003cp>今天跟大家分享了如何学会正确区分概念，让脑子更清楚。学是为了更好的用，晚上大家回到家后，请根据找到正确区分概念的几个步骤，去搞清楚1个概念。 个人微信号：mantoupaojiao。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>\u003cstrong>五、结语（1min）\u003c/strong>\u003c/p>\u003cp>学会独立思考，搞清楚概念，才能让自己脑子更清楚，活的更明白。希望今天分享的独立思考和区分概念能够帮助你获得更好的成长，我是今天的拆书家馒头，谢谢大家的聆听和陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514894140000,"updated_at":1514894140000,"ria":true},{"id":3972,"topic":"做事情最好的开始时间是现在","learn_goal":"学习者能够在现场写出自己要做的一件事情的一个行动步骤。","remark":"大家有没有过自己有很多想做的事情，但因为自己拖延迟迟没做，因为拖延更不想做，于是恶性循环，自己最后忙得焦头烂额，又无力改变？","level":"TF1-2","duration":10,"status":29,"type":0,"chaishujia":{"username":"风信子","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"自我介绍、图书介绍：\r\n研究生（主修土木工程）TF1-2 《把时间当作朋友》不同于我们熟知的时间管理类书籍，这本书的主旨非常简单：时间是不可能被管理的。我们所面临的时间不够用、拖延等问题根本原因出在我们自己身上。我们真正能够管理的，是我们自己。如果我们能开启自己的心智，让自己能够用最可能准确的方式思考、观察、记录、总结、分享和行动，那么自己的时间就会拥有不同的质量，进而整个生活都必然因此焕然一新。这本书可以让我们更好地与自己和平相处。","ratings_count":1,"texts":[{"id":6921,"quote":"\u003cp>还有一个微妙的现象需要注意。尽管在一般的环境中，时间的运动是匀速的，但实际上，就人的主观感受来说，时间的运动肯定是有加速度的。对“为什么随着年龄的增长每个人都会觉得时间过得越来越快”这个问题，心理学家有一个简单明了的解释：\u003c/p>\u003cp>&nbsp; &nbsp;对于一个5岁的孩子来讲，未来的1年相当于他已经度过的人生的1/5，即20%；而对于一个50岁的成年人来讲，未来的1年只相当于他已经度过的人生的1/50，即2%。所以，随着年龄的增长，人们会觉得时间运动得越来越快。\u003c/p>\u003cp>&nbsp;更重要的是，人在小时候没什么事情可做，就愈发感觉时间过得慢；随着年龄增加，要做的事情越来越多，当然就愈发感觉时间过得飞快，稍纵即逝。由此看来小孩子的感觉自然是“那时候天总是很蓝，日子总过得太慢”，而“人生犹如白驹过隙，瞬间而已”大都是老年人地慨叹，也是他们的切身感受。\u003c/p>\u003cp>如果能将这种认识纳入自己的心智，你就不会再对“最后期限”有那么荒谬的幻觉了。只要接受了必须完成的任务，你就会有真切的紧迫感，因为你知道，时间必然越走越快。而且，你现在就已经明白：“最后期限”不是固定在将来的某一点，而是朝着你加速扑来。有的时候，也许还没开始就发现自己已经晚了。在这样的情况下，唯一的策略依然是“现在就开始”--------否则更待何时？在起步晚了的情况下，问题不是“到时候能不能做好”，而是“到时候能做多好就做多好，总好过什么都不做”。明白了这个道理，以后不管遇到什么任务，永远不要再问“什么时候开始才好”，因为答案只有一个：现在！\u003c/p>","explains":"\u003cp>大家工作学习当中都有过需要完成的任务，比如这月底需要交一份报告，一份大作业。但是很多时候我们都拖着懒得做，不愿意做，觉得时间还长，离最后期限早着呢，还来得及，但是我们没有意识到的是人随着年龄的增长会感觉时间过得越快，最后期限朝着我们飞快地扑来，它并不是乖乖地躺在未来的某一天，而这时，当我们意识到这点我们可能会很着急，非常焦虑、手足无措更无法开始工作了，这个时候我们需要做的是降低我们想完成好这份工作的预期，能完成多少算多少，多做一点，这个任务进度条就能多走一点，总比什么都没做强一点。然后立即行动起来。\u003c/p>","interaction":"\u003cp>【A1激活经验】回忆一下，以前有没有过积攒一些工作、学习方面的任务因为各种原因致自己迟迟没开始或者马上到截止日期还没做完的相关经验，这个任务不论是别人布置的（报告、会议记录）或者自己要求自己的有截止日期的任务 （学习某项技能、比如9月要考证）都可以，以桌子为界限分成两组，大家五分钟的时间讨论交流。请一位小伙伴来分享他的经验。\u003c/p>\u003cp>【A2催化应用】请大家想想最近有没有什么任务是订了截止日期还没开始做，或者因为快到截止日期而来不及做而放着不做的任务，想一想现在要做，你会从哪开始做？什么时候开始做？每天愿意做多久？哪怕每天只能匀出时间做10分钟也行，写出你可以做到的具体行动步骤\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1510116089000,"updated_at":1510116089000,"ria":true},{"id":3437,"topic":"预先演练工作法","learn_goal":"学会运用预先演练工作法来处理工作生活中重要的事情，提升满意度","remark":"英爱1-1拆书定级","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"英爱","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是英爱，在一家制药企业从事招商工作。工作之余喜欢是看书、看电影。第一次参加我们拆书帮活动的小伙伴，心里一定会想，“拆书真的要把书给拆了吗？”那么在正式拆书之前，我来给大家简单的介绍下，“什么是拆书”、“什么是拆书帮”。 所谓“拆书”，其实是一种学习方法论，由赵周老师在《这样读书就够了》这本书中首次提出的。“拆书”强调把图书的知识拆页转化为学习者的能力，它以学习者为中心，重在提升学习者解决问题的能力，追求“拆为己用、学以致用”的效果。\r\n 平时我们运用最多的就是“RIA便签读书法”。分为“R、I、A”三个步骤，其中，R是指你阅读的书中最打动你的某个片段； I是你对这个片段的重述。之后，在A的部分，你要拆为己用，A又可以细分为A1和A2两个部分：A1的部分需要结合原文中心思想描述自己的相关经验，最好是失败经验；A2的部分新知识点制定“以后我怎么应用”的行动计划，完成读书从知到行的书面转化。“拆书帮”是基于拆书法的青年公益性学习社群，总舵在北京，目前在全国已有32个城市分舵，还有20多个筹备分舵。拆书帮的使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":6302,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;今天我所分享的片段，来自李笑来老师的《把时间当做朋友》。看书名呢，很多人都会误以为这是一本讲时间管理的书。其实这是一本自我管理的书籍，作者在书中告诉我们，时间是无法管理的，只有通过提高认知，开启心智，才能够让自己的时间变得高效。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;请大家阅读下原文片段，看完的小伙伴可以向我举手示意。\u003c/p>\u003cp>&nbsp;原文片段：\u003c/p>\u003cp>&nbsp;任何事情之前，都会尝试把将要做的事情的整个过程在脑子里预演一遍甚至数遍。有些时候，如果我面临的任务比较复杂，大脑短期记忆容量不够，就只好借助纸和笔（有些人更喜欢使用计算机上的思维导图类软件），用写写画画的方式来辅助自己预演每一个步骤。需要执行的任务越重要，这种预演就越关键。 &nbsp;只有经过大量的预演或者练习，我们才能够在实际执行任务的过程中出色的表现。这也是良性循环和恶性循环之间的选择和差异。\u003c/p>\u003cp>&nbsp;准备充分的人常常会有出色的表现，最终能够顺利地完成任务，而这样的经验会使他更加坚信提前准备的重要。准备不充分的人，执行任务时必然表现欠佳。但不管表现多差，他也提前做了一点准备（或者自认为做了一点准备），但这样的经验却会让他觉得准备是没什么用的，至少是没什么大用，于是下一次他还会采取同样的行动，还会面临相同的甚至更为严重的尴尬……\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;我认为万事皆可提前准备，万事皆需提前准备。只有前期准备充分，才能在实际执行任务的时候，有出色的表现。举个例子，我在新东方做教师培训的时候，经常被新教师夸奖：“李老师，你在台上随机应变的能力太强了！”对此我不敢谦虚——因为他们完全夸错了，我自己太清楚自己的应变能力有多差。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;我之所以“显得”游刃有余，是因为之前做过太多的准备，是因为曾经出过丑——想象一下，在台上讲到一半突然发现自己说的某句话有不曾想到的歧义，是多么窘迫的事情？所以，在任何一次演讲的准备阶段，我都会花时间认真考虑自己的每个观点、每个事例、甚至每个句子可能引发什么样的理解和反应，然后逐一制定对策。只有这样，我才能安心上台。\u003c/p>","explains":"\u003cp>当初刚看到这个片段的时候，我想起一句老话“万事具备只欠东风”。在这里的我们可以把“万事具备”理解为“行动之前把方方面面都安排妥当”，那么在正式执行的时候，就基本不会出现什么疏漏了。\u003cbr>\u003c/p>\u003cp>话虽这么说，但是现在人的生活节奏那么快，工作和生活上要处理的事情实在太多，我想大多数人一定没有提前做准备的习惯。不管是在工作中，还是在生活上，在座的一定也见了不少，因为前期准备不足，后来状况百出的事情。这么说来要想出色完成任务，这个准备工作真是马虎不得。\u003c/p>\u003cp>结合原文，我给出两个步骤，可以实现高效的前期准备。\u003c/p>\u003cp>1、首先是心态上的调整：让自己在内心上真正认识到“预演”的重要性。\u003c/p>\u003cp>2、接下来就是实际操作了，事前把整件事在大脑中演练一遍。借助纸笔或者任何可以帮助你记忆的工具，把自己能够想到的可能出现差错的地方一一记录下来。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;针对可能出现差错的地方，给出两种，至少是一种备选方案，如此反复两次我想基本可以确保万无一失了。\u003c/p>","interaction":"\u003cp>之所以选择这个片段给大家分享，是因为自己有过这方面的惨痛教训。\u003c/p>\u003cp>A1:\u003c/p>\u003cp>&nbsp; 去年八月末是女儿九岁的生日，在我们合肥九岁生日是非常重要的，相当于一个小成人礼吧!为了让女儿有个难忘的生日，早早的我就开始张罗起来了，什么订蛋糕、买生日礼服、给亲朋好友发请帖等等。为了表达我对女儿的爱，还特别用心的花了好几个晚上给她制作了一个成长小视频，计划在女儿生日宴会现场播放。我们小区附近酒店很多，我想提前两周定酒店时间应该是来得及的，结果去订酒店当天，才发现我们带投影设备的酒店包厢都已经定完了，最后只能选择没有投影设备的包厢。一想到自己精心准备的小视频在生日当天不能播放，心里很难受。后来才知道那几天，很多初中生和高中生都在办升学宴，酒店好的包厢都被提前预定完了。后来虽然订到了酒店，但是没有播放视频让我到现在都感到很遗憾。通过这次教训，我知道了事前准备的重要性。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;\u003c/strong> 下月23-24号我们公司要参加联众医药网组织的“湖北新标产品推荐会”，由我做前期的准备和对接工作。因为我是第一次负责这样的工作，为了避免出现差错， 我准备按照以下的流程来做准备。\u003c/p>\u003cp>1、制定流程图，进行纸上预演。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;流程基本就是:确定参会人员、估算预算费用、报批费用、物料准备、会场布置、行程安排。\u003c/p>\u003cp>2、接下来就是根据流程来抓主要负责人，控制时间节点。\u003c/p>\u003cp>与各产品线总监确定的参会人数、参展品种、所需宣传材料，这样才能定下来需要多少预算费用。（还要选择替补人员一名，防止原定人员临时有事无法参加）12号之前沟通完毕。\u003c/p>\u003cp>与分管副总确定预算费用，在15号之前报批完毕。\u003c/p>\u003cp>与办公室主任沟通参会宣传材料等其他物料的准备，要求在20号之前邮寄至办事处。\u003c/p>\u003cp>与湖北办事处经理沟通：会议期间的总部人员接站、住宿酒店的预定、以及会场的提前布置工作。\u003c/p>\u003cp>最后开个碰头会，安排参会人员会议期间的具体工作，落实各项准备工作的完成情况。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;\u003c/strong> &nbsp; &nbsp;今天的分享就到这里，这么看要想出色完成任务其实并不难，关键要看你的前期准备工作足不足了。希望今天的分享能让大家有所收获，期待与大家再次分享拆书的乐趣。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1502879920000,"updated_at":1506050336000,"ria":true},{"id":3326,"topic":"积极鼓励别人","learn_goal":"让学习者了解鼓励的作用和方法","remark":"很多人本能地排斥和他们不一样的想法，当别人寻求建议、表达意愿的时候会不自觉地泼冷水。\r\n其实你只要做对一件事，就会在瞬间与对方建立良好关系，那就是鼓励。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"Andy.Guo","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"自我介绍：\r\n各位伙伴大家晚上好，我叫郭赟，从事外贸行业，也有个英文名字Andy，已婚。在工作和照顾家庭的空闲时间喜欢读书、音乐、健身，也喜欢吃。\r\n拆书帮介绍：\r\n拆书帮很早就听说过，第一次接触是在今年1月2日的线下活动，出于对拆书法的兴趣，就在4月份加入宁波分舵的训练营，并成为了拆书帮光荣的一员。\r\n拆书帮是个怎样的组织呢？我们讲究拆，我就把拆书帮这个词拆开来分析一下。第一个字拆，作为生在China的人，我们对这个字都不陌生，经常见到，拆掉旧的，重建新的。在这里，拆代表着一种以提升能力和解决问题为目标，以成人学习者为中心的学习方法。怎么拆？两种方法，一个是个人学习的便签读书法，适用于自己读书；一个是组织学习的现场学习法，比如说我们今天的这个活动。这两种方法的工具是一样的，那就是RIA，阅读，理解和应用。我一会儿会给大家示范。\r\n第二个字书，我们拆什么？拆致用类图书，是可以解决我们在实际工作和学习中碰到的问题，不是为了考试或考证。\r\n第三个字帮，是个动词，帮助更多人将知识拆解成自己的能力，成为更好的自己并给身边的人带来幸福，这个是拆书帮的主要愿景。帮也是个名词，这个帮是个公益性的组织","ratings_count":0,"texts":[{"id":6175,"quote":"\u003cp>&nbsp;&nbsp;我有一个尽量坚持的原则：永远鼓励身边的人，那怕多少有些盲目。鼓励身边的人，是一种并不被大多数人认为重要的美德。我这么做跟我的经历有关系。总有些人在生活中经常被视为“异类”。也不知道是运气好还是运气差，反正，我从小就一直遇到这个窘境，常常听到老师和同学向我质疑：“怎么就你一个人这样呢？”\u003c/p>\u003cp>在这种意义上讲，我的成长过程非常孤独。年纪不大的时候我就发现，我的脑子里要是蹦出了一个新鲜的主意，最好别说出来。一旦我忍不住说出来，必然惨遭来自各个方向的“冷水”的“袭击”，并且是反复“袭击”。我为此痛苦了很久。终于有一天，我发现，大多数人是以“泼冷水”为乐的。\u003c/p>\u003cp>他们一定要给他们眼中的“异类”泼冷水。泼冷水的愿望之强烈，令人无法想象。那种强烈借助了太多的力量-怀疑、嫉妒、恐惧、愤怒，而在表现的过程中却又披上了另外一层皮-关怀、爱护、友好、帮助。\u003c/p>\u003cp>看清这些后，我作了个决定：从此鼓励身边所有的人，那怕他并不是我的朋友。支持我这么做的另一个理由也来自我的观察。我发现，敢做惊天动地的事情的人，不仅是少数，还是少数中的极少数。所以，鼓励一个人是没有什么风险的。\u003c/p>\u003cp>当我们不停地鼓励所有人的时候，最大的受益者其实是我们自己，因为最终我们会发现，自己开始进入一种他人无法想象的状态，成为一个不需要他人鼓励的人。这一点很重要。因为很多人之所以做事裹足不前，浪费时间甚至生命，原因就在于他们是必须获得别人的鼓励才敢于行动的人。可是，我们却能成为另外一种人-我们可以不需要被别人鼓励-这是一种境界。\u003c/p>","explains":"\u003cp>我个人对这一部分的理解是这样的。\u003c/p>\u003cp>What: 这个片段表达的主要意思是，积极地去肯定对方的想法，去鼓励对方\u003c/p>\u003cp>Why: 为什么要这么做呢？有效的鼓励会让对方敢于说出他新鲜的主意，内心真实的想法，进而感受并得到很大的支持去实现他的愿望。与此同时，我们自己会逐渐成为一个不需要别人鼓励也可以敢说敢干的人。如果不去鼓励而是片面地去打击，会极大地挫伤他的积极性，也不利于我们自身的成长。\u003c/p>\u003cp>How: 怎么才能积极地鼓励到呢？先肯定对方，再分析这个想法的可行性并给到实际具体的建议，最后行动起来帮助他实现这个想法。所以，就四步，肯定、分析、建议和行动。\u003c/p>","interaction":"\u003cp>A1：先问大家个小问题，比如你工作中的同事和你说，我要去西藏旅行一个月，你第一反应是什么？会说工作怎么办、能不能请假、老板会不会辞掉你等等，还是说，不错，想法挺好的。看来大家都是比较理性的人，这也是这个片段拆解的意义。\u003c/p>\u003cp>和大家分享一个我生活中的例子，我老婆喜欢花，她打算在餐桌、卧室、客厅以及房间的角落里都摆上花，吊兰、百合、肉肉什么的，装点家的同时可以愉悦心情。我是个很没生活情调的人，觉得完全没必要，需要时间去打理，花又那么贵，浪费钱嘛。就直接说，这个没有用，浪费时间、钱和精力，不如像我一样，有时间看看书，有钱买些吃的来，多好。她觉得我否定了她，凭什么我要和你一样？最后她还是买了一点，那我也会觉得她不尊重我的意见，彼此因为这点小事闹了别扭，很不好。其实大家从刚才我们看过的片段也发现了，我一开始就做错了。\u003c/p>\u003cp>A2：正确的做法应该是怎么样呢？我理了一下，大家听听对不对。以后她再想买花或别的类似的东西的时候，我就可以用的到了。\u003c/p>\u003cp>1.肯定。花好啊，纯天然的植物，放在家里可以美化环境、净化空气，还让家有了不同的颜色。还是你有想法，有眼光。\u003c/p>\u003cp>2.分析。现在花比较贵，如果在每个角落都放的话，那要好大一笔钱，估计我们这个月就要吃土了。再说鲜花需要去浇水、松土，还得时不时得搬来搬去嗮太阳，需要好多时间的，你应该也没那么多时间去弄吧。\u003c/p>\u003cp>3.建议。你看这样好不好？我们在重要的地方摆上，比如床头、茶几、书桌、餐桌，其他边边角角的地方也看不到，就先不用了。另外，我们可以考虑买些简单的不用侍弄的花，可以自己成长，比如以前买过的满天星，很好看也不用花时间去浇水。\u003c/p>\u003cp>4.行动。我周末去花店看一下，你在网店也留意看看是否有合适的花可以买。周末以前在网上学习一些花瓶摆放的知识，学习一些插花的技巧，让这些花可以创造出最大的美感。\u003c/p>\u003cp>这个做法和之前的那个好？当然是现在这个。区别在那里？之前就是简单粗暴地从分析那一步就否定了，买花不好，不要买，没有鼓励更没有建议和落到实处的行动。\u003c/p>\u003cp>回到刚才同事要去西藏这个例子，应该怎么做？先肯定这个想法，去西藏好啊，再分析和建议，如果去一个月的话，是不是要早点请假，工作也要早做安排，需要我在这段时间顶替你的工作吗？帮助他实现去西藏的这个愿望。\u003c/p>\u003cp>在工作和生活中，我们会碰到很多类似的情况，比如女朋友要买包，同事对工作有个新想法，老板给你安排了新项目，朋友聚餐在那里吃等等。\u003c/p>\u003cp>当然有些是违法乱纪的，比如抢银行，那不适用于我们这个模式。其他合理合法的事情，如果按照肯定、分析、建议和行动来做的话，效果一定不错。\u003c/p>\u003cp>所以，在与人交往，别人向你表达想法的时候，怎么做？四步，肯定、分析、建议和行动。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1501571085000,"updated_at":1507367530000,"ria":true},{"id":3281,"topic":"做一个“给力“”的倾听者","learn_goal":"学习者能够学会如何在适当的环境有效倾听","remark":"拆书家Shooshoo1-1定级","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"Shooshoo","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今晚的拆书家Shooshoo。如果让我用三个标签来介绍自己，我会用“美食爱好者”“手机拍照侠”“0.7文青”。今年我有个大梦想，在2017年成为三级拆书家。另外我也有一些小目标：在2017年，将美食、写作、旅行和阅读一起，融为自我成长的一部分，与大家相互鼓励，共同进步。“拆书”是一种关于成年人学习的方法论，强调以学习者本人为中心，而不是以书本知识为中心，提倡通过学习将知识转化为自己的行动，提升学习者的能力，也就是“拆为己用”。其中最重要的核心就是“RIA便签读书法”：通过R（阅读片段）、I（用自己的话重述知识）、A1（描述自己的相关经验）和A2（以后我怎么应用）几个步骤，让个人读书能达到同主题培训的效果。拆书帮的现场拆书活动，则是由一位拆书家选取出一些片段，组织一场现场学习，引导和促进一群人把知识拆为己用。“拆书帮”是基于拆书法的青年公益性学习社群，总舵在北京，目前在全国已有32个城市分舵，还有20多个筹备分舵。拆书帮的使命是帮助更多学习爱好者成长为拆书家，让更多的人改变他们的学习习惯。","ratings_count":0,"texts":[{"id":6123,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>今天我为大家带来的片段出自于《把时间当做朋友》这本书。我们常说管理时间，但作者的观点是，实际上时间是无法管理的，我们每个人执行的其实是对于时间的认知，以及对于自身的管理，而其中一个重要的部分就是有效沟通。今天我分享的片段，就是针对有效沟通其中的一个很重要的部分：有意识地创造好的沟通环境。\u003c/p>\u003cp>【正文片段】\u003c/p>\u003cp>最后，我们还要养成一个重要的习惯：一旦决定倾听，就要主动帮助说者进入“倾诉”状态。\u003c/p>\u003cp>在课堂上、会议中，打断说者往往不礼貌且没有必要，甚至会浪费他人的时间、破坏他人的注意力。不过，作为听者，尤其是能被说者看到的听者，给予说者鼓励性的信号会使说者更容易地进入“倾诉”状态。尽管我个人极端反对欺骗，但是，我发现哪怕遇到不喜欢的说者和内容（人们往往会因为讨厌内容而讨厌说者，或者反过来，因为讨厌说者而讨厌内容），适度控制自己的反感情绪对获取信息也会有极大的正面作用——既然坐在那里，“听而不闻”就是浪费自己的时间。\u003c/p>\u003cp>然而，当面对面交流的时候，听者的反应会在很大程度上影响说者的状态。尽管人们讨厌自己讲话时被打断，但是也没有人喜欢对没有任何反应的听众讲话。从本质上来看，倾诉其实只有两种：第一种是不顾一切地说出来（比如在教堂里隔着纱窗向神父忏悔），第二种是讲给喜欢听的人。所以，给予说者适当的反应，是听者为了有效倾听必须做的事情。\u003c/p>\u003cp>在自己状态不佳、心不在焉的时候，“马上停止谈话”是对双方都有利的事情。一旦听者决定倾听某人的话，就要想办法调动自己的所有感官去感受说者的一切表达方式，包括他的眼神、姿态、动作等，随时随刻尽可能地去想象说者正在经历的情绪状态。一旦听者开始有意识地做这些事，就会不由自主地真正进入“倾听”状态。而后，更为重要的是，由于听者的专注，说者也将不由自主地进入更深的“倾诉”状态。\u003c/p>\u003cp>有些读者可能会觉得以上描述不知所云，这是正常的，因为绝大多数人都误以为“听”是一个被动的动作，而“说”是一个主动的动作。而事实并非总是如此。善于倾听的人往往会付出很大的努力——因为他们早已习惯，所以并不觉得也不可能觉得辛苦。另外，在很多时候，说者尽管在说，但他们的这个动作也许是被动的。回想一下，我们曾有多少次听到一个人在一口气说了很多话之后慨叹：“我怎么会说这些？”\u003c/p>\u003cp>除了情绪上的反应，我们在更多时候需要通过逻辑上的反应来实现有效倾听。如果读者足够敏感的话，就能体会出“那你的意思是……喽？”和“那你的意思是不是……？”之间的微妙区别——前者多少有些武断，容易导致误解；后者却只是清楚的确认，没有任何副作用。为了能够做到清楚的确认，那些善于沟通的人往往在恰当的时候使用这样的句式：“那你看我这么理解对不对？……”说者这时会自然而然地想尽一切办法表述清楚，甚至在这个过程中会突然发觉自己的疏忽之处，进而没有压力地进行自我纠正。\u003c/p>\u003cp>仔细观察一下就会知道，生活中有多少原本认真的交谈最终变成了激烈的争吵。发生这种情况固然有说者的问题，但更常被忽略却又更为重要的是，听者没有给出恰当的反应——该确认的时候却武断地下了定论，该回应的时候却示以沉默，说者兴高采烈的时候听者却意兴阑珊，说者努力论证的时候听者却过早开始反驳……\u003c/p>","explains":"\u003cp>在座的各位可以回忆一下，自己是不是也曾碰到过这样的情况：\u003c/p>\u003cp>跟对方聊天，但还没说几句，对方开始神游天外，导致你谈兴全无；\u003c/p>\u003cp>亦或者当有人意图跟你沟通的时候，你发现对方说着说着突然开始意兴阑珊，或者欲言又止，最终草草了事。\u003c/p>\u003cp>其实，很少有人注意到，当别人对你说话的时候自己注意力不集中，非常容易引起对方的排斥和反感，匆匆结束了谈话，甚至造成误解，影响到双方感情。\u003c/p>\u003cp>这种情况下，有一大部分原因归结于大多数人并不懂得如何有效的引导倾诉者进入叙述状态。如果听者并没有给说者创造一个良好的倾诉环境，就无法有效地让对方进入顺畅的叙述状态，因而错过了大量关键信息。态度决定命运，此话不虚。信息时代，倾听做不好的话，无形中会带来巨大损失。\u003c/p>\u003cp>行动建议：\u003c/p>\u003cp>1. 避免在自己状态不佳或者心不在焉的时候进行重要沟通，有意识地营造或选择好的沟通环境及状态；\u003c/p>\u003cp>2. 与说话者进行互动：学会用复述确定对方意图，或问句引导后期谈话，让对方知道你在认真倾听并表达已充分的兴趣，同时最大限度的获取信息；\u003c/p>","interaction":"\u003cp>A1(2min)\u003c/p>\u003cp>以前不知道听话人的态度会影响说话人状态这个道理，尤其是面对亲密的人，觉得“大家都这么熟了，不用搞得那么煞有介事，认不认真听也无所谓”，时常嗯嗯哦哦的开个小差。结果有一次两人吵架，才发现由于低效沟通，两人之间已经积累了不少问题。经常是：\u003c/p>\u003cp>我： “你有意见你怎么不早说啊，你不说我怎么知道啊！”\u003c/p>\u003cp>对方：“我说了你听进去了吗？还不如不说呢！”\u003c/p>\u003cp>反复几次以后，我才惊觉是由于我敷衍不上心的态度，导致了对方渐渐失去了跟我沟通的欲望。如果我早点意识到这些问题，可以很大程度上的避免误会。\u003c/p>\u003cp>A2(2min)\u003c/p>\u003cp>本周正在进行董事会安排，为此：\u003c/p>\u003cp>1．我将选择一个合适的状态和时机，与负责就会场和会议准备与双方负责人进行沟通。我会有意识地避开一天中的业务高峰时段，会议集中期以及对方可能正在休息的时间点，尽量选在工作人员精力充沛、事务不拥挤并且自己也心情平和头脑清晰时。\u003c/p>\u003cp>2. 通过过程梳理确认和发问引导，如：会场准备和设备调试有没有足够的人手进行确认和监督？如果没有，是否应该与上级部门沟通，请求增援？各种现场可能遇到的意外情况，我们能有及时应对措施吗？&nbsp;\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>今天的分享就到这里。沟通和交流是两个灵魂靠近的桥梁，无效沟通会让双方渐行渐远，也会无形中损失打两的机会和信息。当为此懊悔不已的时候，首先应该想到的是当时的情境下，自身是否为沟通创造了良好的环境。相信注意到这点之后，会为我们今后的谈话带来无穷的裨益。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500903305000,"updated_at":1506033531000,"ria":true},{"id":3246,"topic":"预演","learn_goal":"通过学会用预演的方式来保证事情的成功率","remark":"拆书家树袋熊贝贝1-1定级","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"树袋熊贝贝","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天分享的拆书家树袋熊贝贝，。我的本名叫张红领，可以把我记忆成少先队员都会带的红领巾。加入拆书帮这个大家庭。希望可以通过学习，可以让自己变得更加优秀。2017年，新年新的气象，我有三个梦想清单：第一，就是要成为三级拆书家，第二，成为一名企业内训师，把自己学到的知识分享给更多的人，去点亮他们的心灯，同时也促进自己的成长。第三，就是2017年要阅读100本书。新的一年，给自己一个崭新的起点，这一年里我会努力实现自己的梦想清单，同时也希望各位小伙伴的新年愿望能够心想事成。\r\n“拆书”是一种学习方法论，强调以学习者为中心而不是以知识为中心，重在提升个人能力、解决问题，追求“拆为己用、学以致用”的效果。 拆书实践最常用的就是便签读书法，通过R（阅读片段）、I（用自己的话重述知识）、A1（描述自己的相关经验）和A2（以后我怎么应用）几个步骤，让个人读书能达到同主题培训的效果。拆书帮的现场拆书活动，则是由一位拆书家选取出一些片段，组织一场现场学习，引导和促进一群人把知识拆为己用。“拆书帮”是基于拆书法的青年公益性学习社群，总舵在北京，目前在全国已有32个城市分舵，还有20多个筹备分舵。","ratings_count":0,"texts":[{"id":6078,"quote":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 预演\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我学编程时用的计算机还很简陋，只有固化的48KB内存，连磁盘都没有。要是电源断了，就什么都剩不了。所以，写出程序以后，要一遍遍地阅读代码，把自己的大脑当成计算机，想象每一行语句执行之后的结果.....如此重复若干，再小心翼翼地将程序输入计算机，还要反复审核是否有输入错误，然后才敢运行它。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;没想到，这种工作模式成了我一生的习惯，我也因此受益无穷。直到现在，我在做任何事情之前，都会尝试把将要做的事情整个过程在脑子里预演一遍甚至数遍。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 有些时候，如果我面临的任务比较复杂，大脑短期记忆容量不够，就只好借助纸和笔（有些人更喜欢使用计算机上的思维导图类软件），用写写画画的方式来辅助自己预演每一个步骤\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;需要执行的任务越重要，这种预演就越关键。只有经过大量的预演或者练习，我们才能够在实际执行任务的过程中有出色的表现。这也是良性循环和恶性循环之间的选择和差异。准备充分的人，常常会有出色的表现，最终能够顺利地完成任务，而这样的经验会使他更加坚信提前准备的重要。准备不充分的人，执行任务时必然表现欠佳，但不管表现多差，他也提前做了一点准备（或者自认为做了一点准备），但这样的经验会让他觉得准备是没有什么用的，至少是没什么大的用的，于是下一次他还会采取同样的行动，还会面临相同的甚至更为眼中的尴尬。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;我认为，万事皆可提前准备，万事皆需提前准备。只有前期准备充分，才能在实际执行任务的时候有出色的表现。举个例子，我在做新教师培训的时候，经常被新教师夸奖：“李老师，你在台上随机应变的能力太强了！”对此我不敢谦虚—因为他们完全夸错了，我自己太清楚自己的应变能力有多差。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我之所以“显得”游刃有余，是因为之前做过太多的准备。之所以做那么多的准备，是因为曾经出过丑—想象一下，在台上讲到一半突然发现自己说的某句话有不曾想到的歧义，是多么尴尬的事情？所以在任务一次演讲的准备阶段，我都会花很多时间认真考虑自己的每个观点、每个事例、甚至每个句子可能引发什么样的理解和反应，然后逐一制定对策。只有这样，我才可以安心上台。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 在生活和工作中，会出现两类人，一类人是做事非常有条理性，不慌不忙。一切都按照自己的想法有序进行。另一类人是做事风风火火，毫无章法可言，做的事情不是这个地方不好就是在别的地方有疏忽的，经常是险象环出，疲于应付，给人留下一个不好的印象。这两类人最大的区别就在于，第一类人会在遇到事情前，会对事情的流程和中间出现的环节进行预演，充分考虑所有的情况，可以做到一切尽在掌握。而第二类人，只会做一点点小的准备或者依靠过去的经验，凭感觉来做事，导致现场出现很多没想到的问题。从而带来诸多不好的影响。\u003cbr>\u003c/p>\u003cp>结合原文片段，给到以下【行动建议】：\u003c/p>\u003cp>第一，遇到事情，首先要整理出活动流程，细化到每个部分，并且分配到个人\u003c/p>\u003cp>第二，根据事情的重要程度和复杂程度，可以在脑子里或者借助思维导图上进行预演，充分考虑到各个方面；\u003c/p>\u003cp>第三，大量的预演和练习，一方面有利于事情发展在掌控之中，另一方面可以让这样的方法最后变成本能的反应。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp; 每到年底的时候，公司都会开公司的年会，去年公司让我做年会的总导演，来协调各个部门的节目编排，公司要求一定要把年会做好，因为到时候还会邀请一些经销商过来参加。要体现公司的精神面貌和形象。由于第一次负责公司年会，没有经验，一方面没有对各个部门进行详细的协商和当天工作人员的分工，另外一方面，也没有进行过一次像模像样的整体彩排，对每个节目的时间和主持人之间的沟通也是欠缺，只在当天演出前三个小时草草的进行了一遍过场，导致当天的演出出现了很多意外的状况，比如：音乐放错、上一个节目结束，下一个节目的人员还出现未到位的情况、礼品的摆放不到位、因为没有对讲机，导致我全场要跑着去找人，去协调节目之间的衔接等等，现场是险象环生。出现了很多的小问题，同时没有制定出现问题的应急预案。年会结束后后被老总叫到办公室大骂一顿\u003c/p>\u003cp>今年公司和珠江集团形成战略合作关系，准备开展珠江艾诺教育的招商加盟工作，要在安徽召开招商加盟会议，公司让我负责整个会议。\u003c/p>\u003cp>经过研究和考虑，我会从一下几个方面入手准备：\u003c/p>\u003cp>一、把招商加盟会议的流程写下来，先在脑子里预演一遍，看看有没有遗漏的环节\u003c/p>\u003cp>二、根据加盟商的名单，准备好礼品和邀请函，把这件事分配到个人，进行专项负责，出现问题追究和人责任\u003c/p>\u003cp>三、提前一星期在会议现场安排流程预演两遍，熟悉场地和现场的布局\u003c/p>\u003cp>四、向公司汇报预演情况以及注意事项\u003c/p>\u003cp>五、制定招商加盟会议流程的思维导图，在会议开始前在脑海里进行最后的预演，进行查缺补漏。\u003c/p>\u003cp>&nbsp;&nbsp;今天我的分享就到这里。希望我以上的案例和方法可以对你的工作和生活有所帮助。期待大家下次来拆书帮，分享你们运用之后的心得。在拆书帮这个大家庭里。希望我们一起前行，成长为自己想要的样子。谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500383166000,"updated_at":1507721577000,"ria":true},{"id":2937,"topic":"把时间当朋友","learn_goal":"通过预演让自己游刃有余","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"树袋熊贝贝","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天分享的拆书家树袋熊贝贝，。很多人都会问我，为什么一个男孩子取一个这么女性化的名字，这是因为我的女朋友叫考拉宝宝。为了体现心里有她，所以起了这个名字。我的本名叫张红领，非常的好记，你们可以把我记忆成少先队员都会带的红领巾。这样是不是很容易记住我了。加入拆书帮这个大家庭。希望可以通过学习，可以让自己变得更加优秀。让自己成为自己想要的样子，不想在浑浑噩噩的度过这一辈子。同样也希望在学习的过程中认识更多的小伙伴，大家可以一起前行。因为一个人可以走的很快，但是一群人可以走的更远。2017年，新年新的气象，我有三个梦想清单：第一，就是要成为三级拆书家，第二，成为一名企业内训师，把自己学到的知识分享给更多的人，去点亮他们的心灯，同时也促进自己的成长。第三，就是2017年要阅读100本书。新的一年，给自己一个崭新的起点，这一年里我会努力实现自己的梦想清单，同时也希望各位小伙伴的新年愿望能够心想事成。","ratings_count":0,"texts":[{"id":5724,"quote":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;预演\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 我学编程时用的计算机还很简陋，只有固化的48KB内存，连磁盘都没有。要是电源断了，就什么都剩不了。所以，写出程序以后，要一遍遍地阅读代码，把自己的大脑当成计算机，想象每一行语句执行之后的结果.....如此重复若干，再小心翼翼地将程序输入计算机，还要反复审核是否有输入错误，然后才敢运行它。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;没想到，这种工作模式成了我一生的习惯，我也因此受益无穷。直到现在，我在做任何事情之前，都会尝试把将要做的事情整个过程在脑子里预演一遍甚至数遍。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 有些时候，如果我面临的任务比较复杂，大脑短期记忆容量不够，就只好借助纸和笔（有些人更喜欢使用计算机上的思维导图类软件），用写写画画的方式来辅助自己预演每一个步骤\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 需要执行的任务越重要，这种预演就越关键。只有经过大量的预演或者练习，我们才能够在实际执行任务的过程中有出色的表现。这也是良性循环和恶性循环之间的选择和差异。准备充分的人，常常会有出色的表现，最终能够顺利地完成任务，而这样的经验会使他更加坚信提前准备的重要。准备不充分的人，执行任务时必然表现欠佳，但不管表现多差，他也提前做了一点准备（或者自认为做了一点准备），但这样的经验会让他觉得准备是没有什么用的，至少是没什么大的用的，于是下一次他还会采取同样的行动，还会面临相同的甚至更为眼中的尴尬。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp;我认为，万事皆可提前准备，万事皆需提前准备。只有前期准备充分，才能在实际执行任务的时候有出色的表现。举个例子，我在做新教师培训的时候，经常被新教师夸奖：“李老师，你在台上随机应变的能力太强了！”对此我不敢谦虚—因为他们完全夸错了，我自己太清楚自己的应变能力有多差。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 我之所以“显得”游刃有余，是因为之前做过太多的准备。之所以做那么多的准备，是因为曾经出过丑—想象一下，在台上讲到一半突然发现自己说的某句话有不曾想到的歧义，是多么尴尬的事情？所以在任务一次演讲的准备阶段，我都会花很多时间认真考虑自己的每个观点、每个事例、甚至每个句子可能引发什么样的理解和反应，然后逐一制定对策。只有这样，我才可以安心上台。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp;在生活和工作中，会出现两类人，一类人是做事非常有条理性，不慌不忙。一切都按照自己的想法有序进行。另一类人是做事风风火火，毫无章法可言，做的事情不是这个地方不好就是在别的地方有疏忽的，经常是险象环出，疲于应付，给人留下一个不好的印象。这两类人最大的区别就在于，第一类人会在遇到事情前，会对事情的流程和中间出现的环节进行预演，充分考虑所有的情况，可以做到一切尽在掌握。而第二类人，只会做一点点小的准备或者依靠过去的经验，凭感觉来做事，导致现场出现很多没想到的问题。从而带来诸多不好的影响。\u003cbr>\u003c/p>\u003cp>结合原文片段，给到以下【行动建议】：\u003c/p>\u003cp>第一，遇到事情，首先要整理出活动流程，细化到每个部分，并且分配到个人\u003c/p>\u003cp>第二，根据事情的重要程度和复杂程度，可以在脑子里或者借助思维导图上进行预演，充分考虑到各个方面；\u003c/p>\u003cp>第三，大量的预演和练习，一方面有利于事情发展在掌控之中，另一方面可以让这样的方法最后变成本能的反应。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;每到年底的时候，公司都会开公司的年会，去年公司让我做年会的总导演，来协调各个部门的节目编排，公司要求一定要把年会做好，因为到时候还会邀请一些经销商过来参加。要体现公司的精神面貌和形象。由于第一次负责公司年会，没有经验，一方面没有对各个部门进行详细的协商和当天工作人员的分工，另外一方面，也没有进行过一次像模像样的整体彩排，对每个节目的时间和主持人之间的沟通也是欠缺，只在当天演出前三个小时草草的进行了一遍过场，导致当天的演出出现了很多意外的状况，比如：音乐放错、上一个节目结束，下一个节目的人员还出现未到位的情况、礼品的摆放不到位、因为没有对讲机，导致我全场要跑着去找人，去协调节目之间的衔接等等，现场是险象环生。出现了很多的小问题，同时没有制定出现问题的应急预案。年会结束后后被老总叫到办公室大骂一顿\u003c/p>\u003cp>今年公司和珠江集团形成战略合作关系，准备开展珠江艾诺教育的招商加盟工作，要在安徽召开招商加盟会议，公司让我负责整个会议。\u003c/p>\u003cp>经过研究和考虑，我会从一下几个方面入手准备：\u003c/p>\u003cp>一、把招商加盟会议的流程写下来，先在脑子里预演一遍，看看有没有遗漏的环节\u003c/p>\u003cp>二、根据加盟商的名单，准备好礼品和邀请函，把这件事分配到个人，进行专项负责，出现问题追究和人责任\u003c/p>\u003cp>三、提前一星期在会议现场安排流程预演两遍，熟悉场地和现场的布局\u003c/p>\u003cp>四、向公司汇报预演情况以及注意事项\u003c/p>\u003cp>五、制定招商加盟会议流程的思维导图，在会议开始前在脑海里进行最后的预演，进行查缺补漏。\u003c/p>\u003cp>&nbsp; 今天我的分享就到这里。希望我以上的案例和方法可以对你的工作和生活有所帮助。期待大家下次来拆书帮，分享你们运用之后的心得。在拆书帮这个大家庭里。希望我们一起前行，成长为自己想要的样子。谢谢大家。\u003cbr>\u003c/p>\u003cbr>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497540998000,"updated_at":1497541726000,"ria":true},{"id":2903,"topic":"能够正确面对不满意的现状，进而获知进步的关键策略。","learn_goal":"能够正确面对不满意的现状，进而获知进步的关键策略。","remark":"","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李明","city":"北京市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"刚才讲了些这次拆书的要求和注意事项，接下来正式开始2-1的拆书。\r\n大家好，我叫李明，这次咱们一起来拆解《把时间当做朋友》中的一个对我启发很大的片段。\r\n【设置目标】：在跟随我完成本次拆书学习后，我们能够明确现状无法马上摆脱的事实，之后再遇到对现状不满或者憧憬“理想职业”时不再懈怠，而是能回想到今天拆书内容而专注于手中的工作，进而处于进步的良性循环之中。\r\n【分组】：3人一组，等会会给时间在小组内反思、探讨自己的相关经验，然后会请一位伙伴作为代表分享。\r\n【Feature特征】：《把时间当做朋友》豆瓣评分8.5分，有24436人评分。作者李笑来从心智成长的角度来谈时间管理。\r\n【Advantage优势】：这本书是个人成长类书籍中很畅销的一本，作者论证的同时给出很多切实可行的方法论。\r\n【Benefit利益】：作者引述自己从事的职业中所遇到的事例，告诉我们：如何打开心智，如何运用心智来和时间做朋友，如何理解时间管理的意义。之后再说到时间管理，不是简单地利用各种节省时间的方法论，而是从心智层面上理解时间不可管理，只能和时间做朋友（更清晰地认知时间）。","ratings_count":0,"texts":[{"id":5686,"quote":"\u003cp>尽管天分很重要，但一个人的能力主要靠积累获得。从一个人开始从事一个职业的那一瞬间起，只要足够认真、努力，他的能力就会不停的积累。如果这个人实际上向往的是另一个职业，那么他的所谓“梦想”几乎必然使他在当前这份职业上心不在焉、无甚积累。其实，世界上80%以上的职业并不过分依赖天分，更可能甚至几乎只依赖积累。天长日久，这个人在当前的职业中将逐渐落后于那些认真做事的人。\u003c/p>\u003cp>……\u003c/p>\u003cp>几年过去，这个人在他的所谓梦想职业中的经验积累依然是零，依旧只是空有梦想。还有一个他更可能宁愿视而不见的事实是，那些在他所谓梦想职业中拼搏努力的人在这段时间里已经积累了无数经验，磨练出他在圈外无法想象的各种能力。就算有一天这个人有足够运气进入了他那个他梦寐以求的领域，结果可能还是发现自己一无所有，毫无竞争力，最后不过是一切清零从头再来。\u003c/p>\u003cp>……\u003c/p>\u003cp>越是不满现状，摆脱现状的欲望就越强烈，而这种欲望会让一个人最终迷失方向。因为无论是谁，从本质上看都无法摆脱现状，每一时刻的现状都是过去某一或者某些时刻的结果，而每一时刻的现状都是未来某一或者某些时刻的原因。\u003c/p>\u003cp>……\u003c/p>\u003cp>对现状不满，急于摆脱现状，是人们常常不知不觉落入陷阱（尽管偶尔这也是少数人真正的动力）。接受现状才是最优策略——有什么做什么，有什么用什么；做什么都做好，用什么都用好。不要常常觉得苦（这会让人忍不住顾影自恋，浪费精力与时间），而要想办法在任何情况下找到情趣——快乐是一种本事。这些年我遇到的几乎所有优秀的年轻人都有这样的特征：他们很少对现状不满（可能是他们的优秀使他们难以觉得不满吧），他们热爱自己的生活，他们相对更不在意外界的影响，他们更专注于做事而心无旁骛，他们身处良性循环之中，当然，他们也因此每时每刻都在进步。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导--有举例以及强调不按照拆页行动建议的坏处 &nbsp;\u003c/strong>\u003c/p>\u003cp>【举例】：之前做围棋教师时只是完成工作，没有专注，结果进步很有限。其实那时空闲时间很多，如果能够专注于工作，专注于围棋技能的练习和幼少儿教育知识的体系化，那么现在很可能达到围棋业余2段水平，1年多的时间足够将幼少儿教育知识体系化。\u003c/p>\u003cp>对现状不满，我们可能都会遇到；梦想职业，我们可能都会有。然而这些可能都是陷阱，接受现状才是最有策略，做好正在做的工作，专注于做事、心无旁骛，才能处于良性循环之中，从而获得更多进步。\u003c/p>\u003cp>【不按拆页行动的坏处】：反之如果我们一味沉浸在对现状的不满和对理想职业的向往中，那肯定无法专注于当前的工作，工作无法全力以赴，那么在工作中的积累会受到限制，这会阻碍我们积累和进步，必然落后于那些认真工作的人。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1\u003c/strong>\u003cstrong>】激活经验--显像问题 &nbsp;\u003c/strong>\u003c/p>\u003cp>【提问设计】：结合你工作的现状，想一想你对现状是否满意？是否觉得工作太琐碎、没意思，发展空闲有限？是否幻想更好的职业，有更高的待遇，更能充分发挥自己的能力？\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 鲁丽芳：刚入职时，觉得QA很重要，后来才发现其实并不在核心流程内。很多时候，客户会随时改动需求，那技术端就只能尽快修改、满足，我们QA根本没时间优化。\u003c/p>\u003cp>（2）&nbsp;&nbsp; 窦鹏飞：国土资源局工作很清闲，没啥成长空间。然后来参加咱们拆书帮、兼职做保险来锻炼能力。现在也在主动找工作中可以发展的机会，前段时间还和领带提议做下次会议主持，即便是照着逐字稿念，也要干。\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工 &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>【设计提问】：结合本次学习了解到的方法，谈谈你对目前工作的看法？如果再有对现状不满或者幻想“梦想职业”时，你应该怎么做，从而确保处于良性循环中？\u003c/p>\u003cp>请在小组之间讨论，给出具体的情形和行动步骤，每个人2分钟时间。\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 资言：做了三年多的全职妈妈。刚开始大半年完全以孩子为中心，没有什么自我。之后机缘巧合下，开始写书评，和各大出版社合作，可以免费阅读很多书籍；最近在运营自己的公众号，也是一个很好的开始吧。今后避免对现状不满和幻想，专注于做好书评人和公号运营者。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1497269493000,"updated_at":1497269569000,"ria":true},{"id":1944,"topic":"兴趣不是天生的，而是后天反复习得的技能","learn_goal":"做好一件事，并且比别人做得好，那么兴趣自然而然也就产生了","remark":"先从反面描述这本书，这样大家就对“它究竟是什么”这个问题可能就不言自明了。这本书不是时间管理书籍；不是成功学书籍；不是心灵鸡汤式书籍；不是一本讲大道理的书；不是一本随便翻翻就可以的书。这本书是李笑来老师写得一本难得的书，与你我一起分享难得的经验与思考。这本书从心智成长的角度来谈自我积累，笑来老师通过自己职业生涯中遇到的实例，告诉我们：如何打开心智，如何运用心智来和时间做朋友，从而开启人生的成功旅程。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"小猴儿精","city":"太原"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"大家好，我是静静，目前是一名即将硕士毕业的老生。我的代名词朴素简单沉闷有耐心，美名其曰理科女。你说我安静，可我的内心如此躁动，事事怀有好奇心又富有激情。跑步是我消除坏情绪的方法之一；羽毛球是我最擅长的球类运动；看书的习惯源于我爸。我深知自己资历尚浅，所以很难做到知行合一。在这里请大家多多指教，互相学习，互帮互助，一起加油吧！\r\n拆书：从词性上来看，是一个动词。拆书除了读书（单向性输入）外还包括输出，通俗来讲就是把知识拆为已用，做到学以致用。拆书的主体可以是个人或者集体。个人拆书用便签法，集体拆书是由一位拆书家引导群体把知识拆为已用，将知识多元化扩展开来，从而更深刻地理解。类比学习。除了掌握基本的概念外还要学会做题，学会举一反三，只有这样才能把知识融会贯通，做到深刻理解，加深记忆。拆书就是做题的过程，自己举例，自己解决。\r\n拆书帮：名词，是一个“公益性组织”，多人学习模式，还可以帮助更多学习爱好者升级为拆书家。类比学习。每个人的做题方法都不一样，多人在一起做题，我们可以得到不同于自己的解题思路与技巧。多元思维相互碰撞，加之浓重的学习氛围，让学习更有动力，更富有感染力。","ratings_count":0,"texts":[{"id":4558,"quote":"\u003cp>经常有学生向我表示他对目前的专业没兴趣——他真正感兴趣的是某某专业。看得出来，这些人常常不快乐，因为他们（觉得）自己正在做自己不喜欢做的事情然而，事实果真这样吗？不客气地说，在99%的情况下，并非如此。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;首先，这些人其实并不是对自己正在做的事情没有兴趣，而是没有能力把目前正在做的事情做好。对一个人来说，一定要问自己这个问题：我不喜欢做某件事情，是不是仅仅因为这件事我没有做好？若是因为自己没有做好而不喜欢，就要考虑另一个问题：做好这件事情究竟对自己有没有意义？如果有，那就要努力做，直到做好为止，没有其他选择。反过来，自己做得挺好，但就是不喜欢，纯粹因为那件事对自己确实没有什么吸引力——事实上这种情况少之又少——那就直接换一件事情做吧。谁能逼你去做一件你确实不喜欢做的事情呢？退一步说，如果你被逼着去做自己能做好的事情，应该也会有些兴趣的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;其次，人们总说他们真正感兴趣的是其他事情。可事实上，出现这种感觉应该仅仅是因为他们还没有开始做那件事，也还没有在那件事上遭受挫折而已。其实，很多人真的放弃原来做的事情，转去做新的“真正感兴趣的”事情的时候，往往会发现，这件事想要做好同样困难重重，挫折不断。没过多久，这些人又会因为做不好这件事情而对其失去兴趣，然后开始幻想做另外的事情，并且将这一行为“合理化”：“我（才知道）自己真正感兴趣的并不是这个……”\u003c/p>\u003cp>综上所述，我觉得兴趣并不是很重要，至少没有我们想象得那么重要。对一个人来说，某件事情只要能做好，并且做到比大多数人好，他就不会对那件事情没兴趣。培养孩子的兴趣，不是买来一架钢琴或者一本书就可以的。正确的做法是：根据孩子的情况，选出孩子最可能做得比别人好的事情（这很可能已经是极其耗时费力的了）；然后还要绞尽脑汁让孩子学得会、做得好、做得比一般人好、做得比谁都好——兴趣就自然出现了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;说来说去，是顺序出了问题：往往并不是有兴趣才能做好，而是做好了才有兴趣。 人们总是搞错顺序，并对这样的错误毫不知晓。虽然并非绝对，但完成大多数事情，确实都需要熟能生巧。做得多了，自然就能擅长；擅长了，自然就做得比别人好；做得比别人好了，兴趣就浓起来了，而后就更喜欢做、更擅长……进入良性循环。可同样的，做得多，就需要大量的时间投入，所谓“没兴趣”，往往不过是结果，如果将它当作“不去做好”的理由，最终的惩罚就是大量时间白白流逝。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;片段节选自《把时间当作朋友》李笑来 P242\u003c/p>","explains":"\u003cp>&nbsp; 兴趣不是一开始发现的，而是在持续学习的过程中习得的。我们总以为某件事做不好是因为没兴趣，其实真正原因是没有能力做好这件事。其次，出现这种感觉是因为还没有开始做自己认为感兴趣的事，也没有在做事的过程中遇到挫折而已。总之，并不是有兴趣才能做好，而是做好了才有兴趣。\u003c/p>\u003cp>&nbsp; 所以要想做好某件事便要从一而终，并且相信自己能做好，做到熟能生巧，在这件事上花费时间越长，回报越高，慢慢就产生兴趣了，从而进入良性循环，并且相信积累的力量，发展更多的兴趣。\u003c/p>","interaction":"\u003cp>A1:话说之所以我学数学专业其实并不是因为我感兴趣，中学时代苦逼学了多年数学已经把我折磨得够呛了，谁会乐意让它继续折磨我啊（即便我当时数学成绩确实不错）！就这样在大学专业数学环境的进一步熏陶下，我依旧没能把它学好（因为它的确很难）。我只是掌握了基本知识，接触了各方面有关数学的书籍。我承认自己在数学方面的造诣会一直处于二流水平，但现在至少我不排斥它。别人都说学数学的女生balabala（各种优点），我也只能送他迷之微笑。考研时我一直在犹豫到底要不要换专业，因为我深知自己不是学数学的好苗子，另外我也想接触别的专业，不想和数学死磕到底。我咨询了一位长者的建议，他给了我极大的信心让我继续学数学。既然学了这么久多少是自己熟悉的知识，而如果重新接触一门新专业，那所学的东西将会更多，同样付出的精力也要与时间匹配。另外若我选了别的专业未必就是自己真正感兴趣的，有可能在学习的过程中发现原来比想象中还难，能否考上的概率自己掂量一下便知，想要一次性通过，那就靠谱点做自己会做的。\u003c/p>\u003cp>A2:事实上我也这么做了，并且也做对了。数学带给我的是更深入的思考，我很享受思考的过程。我开始接触中学数学，凭借数学的底子，我有自信上高中的课程，从多年兼职家教经历中我找到了自信，并且坚信我会一直把它做下去，做到精进，做到通透。如今高中数学已经成为我不可缺少的一部分，当然也是我主要的经济来源。它带给我更多的是思考，有逻辑地思考，更加深入地思考。有时候我会觉得它很有趣，当我用新的思维方式联系某些知识点时。对于我现在学的数学，我也能顺利地接受并做好它。\u003c/p>\u003cp>&nbsp;&nbsp;另外我一直喜欢的心理学也开始有了起色。如今已报名培训班，备考5月份心理咨询师考试。我想之所以喜欢，可能是因为读的大部分是伪心理学（偷笑）。当我真正接触心理学最初始的知识时，我想是枯燥又无聊的，那也没关系，想想我的数学是怎么学会的便接受了。新的一年到来，我要有仪式感地迎接它。我更愿意接触文字，在文字的海洋中汲取养分。争取做到理科是面子，文科是里子，多维发展，从而发现自己的价值所在。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487049149000,"updated_at":1487049398000,"ria":true},{"id":1670,"topic":"6个方法，拯救拖拉，提升效率","learn_goal":"复述战胜拖拉的6个步骤，小组讨论自己以往的经历，并规划应用","remark":"办事拖拉实际上是“学习能力欠佳”的最终表现。克服办事拖拉的毛病，应该从全面正视任务开始。找到了症结所在，就有办法找到对策。\r\n●先分析任务所需技能；\r\n● 正视自己技能熟练程度；\r\n● 针对技能上欠缺开始学习；\r\n● 擅长部分放到后面；\r\n● 记录、监督；\r\n● 按部就班完成计划。","level":"TF2-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"悠南","city":"大连"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是悠南，陶渊明笔下“悠然见南山”就是我啦，我是一名热爱文字和声音的大三工科女，自由写作者，读书写字是我生活不可或缺的一部分，目前是简书推荐作者，今日头条受邀入驻作者，自媒体写作者，还有一个狂热的兴趣是养生，规律作息，运动健身、养生养颜，努力做一个有思想、有深度、有担当有颜值的女子。","ratings_count":0,"texts":[{"id":4285,"quote":"\u003cp>所以，很多人实际上根本不知道自己所谓的“喜欢做某件事情”实际上更可能只不过是因为那件事情相对简单、容易获得奖励而已。办事拖拉的人其实并非不做事，他们做事，甚至做很多事；他们也并非“不努力”，他们花很长时间去做事——只不过他们花费很多时间只做很多非常容易的事情。\u003c/p>\u003cp>因此他们没有效率——实际上，准确地讲，他们总是完成不了任务。因为在现实生活中基本上每一个任务都是“系统工程”，即，每个任务其实总是由许多需要不同技能的任务组成。最终只有那些全面掌握这些（而不是某一个）技能的人才能够完成任务。\u003c/p>\u003cp>这样来看，办事拖拉实际上是“学习能力欠佳”的最终表现。克服办事拖拉的毛病，应该从全面正视任务开始。找到了症结所在，就有办法找到对策。\u003c/p>\u003cp>● 做任何事情之前，花上一定的时间分析完成任务所需的种种技能；\u003c/p>\u003cp>● 诚实面对自己，正视自己相对于这些技能上的熟练程度；\u003c/p>\u003cp>● 如果自己在某些技能上有所欠缺，那么a．短期：求助于他人；b．长期：求人不如求己——开始学习；\u003c/p>\u003cp>● 测算时间，把自己擅长的部分放到后面可能是优势策略；\u003c/p>\u003cp>● 养成记录的习惯，以便自己随时监督自己；\u003c/p>\u003cp>● 按部就班完成计划。\u003c/p>","explains":"\u003cp>生活中，你是否有一些早早该做的事情一拖再拖，到最后草草结束或是直接放弃？总有一些完美的规划在心里搁置了很久却迟迟没有行动？这种情况称之为拖拉。绝大多事的拖拉实质上是是学习能力欠佳的表现。克服办事拖拉的毛病，应该从全面正视任务开始。找到了症结所在，就有办法找到对策。\u003c/p>\u003cp>克服拖拉的几个方法步骤：\u003c/p>\u003cp>第一，做事之前，花上一定的时间分析任务所需的技能，第二，正视自己相对于这些技能上的熟练程度；第三，如果自己在某些技能上有所欠缺，那么a．短期：求助于他人；b．长期：求人不如求己——开始学习；第四，测算时间，把自己擅长的部分放到后面；第五，养成记录的习惯，以便自己随时监督自己；第六，制定计划按部就班完成。\u003c/p>\u003cp>在这里给大家举个反面例子：\u003c/p>\u003cp>我今年暑假在公司实习的时候，领导交给我一个任务：通过网站的用户登录对全公司7000多人做一个大致的用户画像，并输出竞品报告，给我的时间是一个月，我当时一想时间还早着呢，就没有去认真规划，半个月过去了，我才发现这个任务比我想象中的要难，后来又因为总有一些琐碎的任务让我把这件事搁置了，直到一个月以后我即将离职的最后一周我才加班加点地勉强交了一份很菜的答卷。我永远也忘不了领导当时那失望的表情。\u003c/p>\u003cp>那么在这件事情上我应该如何运用今天的方法步骤克服拖拉呢？\u003c/p>\u003cp>首先，在领导交给我做用户画像这个任务后，我应该花点时间分析完成这项任务所需的技能，如市场调研，ppt制作，用户研究等，其次正视自己相对于这些技能的熟练程度，当我发现我有某方面不擅长时，可以短期内请教公司前辈或者干脆自己学，同时预估一下时间，把自己擅长的部分放到最后，养成记录的习惯，随时监督自己，制定计划有序地去完成。那么我相信，结果也不至于让我现在如此愧疚了。\u003c/p>\u003cp>（不这么做的坏处）大家可以设想若我没按照文中的步骤，最后我会令领导大失所望，甚至直接被炒鱿鱼。所以如果我们做事之前没有认真思考完成任务所需技能和时间规划，很容易让我们的生活弄得一团糟，导致办事拖拉，影响效率。\u003c/p>\u003cp>值得一提的是，以上这些方法是有一定的适用条件的，比如这是一个人的自我管理策略，如果你是一个团队的管理者，你需就需要另谋他法了。\u003c/p>","interaction":"\u003cp>你有没有过这样拖拉的经历：开学的时候就信誓旦旦地想要在寒假找一份好的实习，简历却迟迟没有做起来？看到很多人投身自媒体写作，你很早就想弄个公众号好好写点东西，公众号开通之后却没写几篇文章？答应朋友要做的事情一拖再拖之后发现无从下手？看到别人姣好的身材早早决定运动健身却因为别的事情一次次地被搁置？\u003c/p>\u003cp>请大家\u003cstrong>回顾最近的一次\u003c/strong>的“拖拉”行为，是什么事情？按照刚才拆页中的方法，并想想，以后再遇到这样的行为，应该怎样应用刚才所学，减少“拖延”行为的产生？请在组内和你的小伙伴分享，之后我们请一个小伙伴进行发言，描述如何应用所学，解决最近的一次“拖拉”的行为。\u003c/p>\u003cp>学习者分享：（高先生）\u003c/p>\u003cp>结语：\u003c/p>\u003cp>成功者相对大部分人最大的特点他们能比较高效地管理时间，大多数的成功根本与智商没有任何关系，失败大多是因为不会精确地管理时间，拖拉是现实生活中很多人多多少少会犯的毛病，拖拉不可怕，可怕的是我们明知自己有这个毛病却依旧无动于衷，想要更好地进行时间管理，提高效率最有效的方法是克服拖拉，让我们一起通过这6个方法改善自己学习“能力欠佳”的表象，拯救拖拉，高效做事。我是今天的拆书家悠南，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482470490000,"updated_at":1482470490000,"ria":true},{"id":1524,"topic":"学会倾听","learn_goal":"通过今天的学习，能够用三个方法加强自己的倾听能力。","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"朱依凌（鱼小刺）","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家鱼小刺，今天是我TF3-1的练级现场哦，感谢在座各位小伙伴的参与。\r\n【设定学习目标】今天大家在跟随我完成本次的RIA现场学习后，能够学会积极倾听他人的方法，从而让我们在和他人的谈话中，和对方越聊越开，话题不断深入，增强人际沟通里与对方的联结能力。","ratings_count":0,"texts":[{"id":4054,"quote":"\u003cp>\u003cstrong>（事件场景）\u003c/strong>在家里我经常会遇到这样的情况，老公有时候下班回来好像蛮有和我沟通的欲望的，这个时候他会用一种舒服的方式窝在沙发里，然后开始和我聊天，巴拉巴拉说一堆他单位的事情，然后我就会嗯、啊、哦地表达我在听他说话，手里还会忙着收拾东西，然后每次他都会气急败坏地说：“你一点也不想听我说话，算了，不说了！”我也很委屈地说：“我在听你说话啊，刚才你不就是说了单位的XXX事吗？你看我都听到了啊！”但是这个时候，对方已经很不开心地闭嘴了，摆出一副和你说了你也不懂的表情，结果就是谈话不欢而散。其实我真的是错过了一次和老公建立亲密关系的机会呢。\u003c/p>\u003cp>\u003cstrong>（提问）\u003c/strong>我想问下你们，是不是经常有这样的情形：其实我是“怀着一颗赤诚的心”和对方交流的，结果却闹的彼此都很郁闷？俗话常说“听话要听音儿”，我明明觉得自己很用心听对方说话了呀，但是为什么对方并不领情呢？\u003c/p>\u003cp>（影响）我们都有这样的体会，在交谈中如果对方认真倾听，我们心里就会比较舒坦，而且愿意和对方进一步联系。如果对方不关注我们说的内容，就好像在传达这样的意思：“我对你不感兴趣，我真的不关心这些。我更感兴趣的是自己。”这样说可能并不准确，但是，我们确实会解读出类似的信息。其实，交谈的双方都有被倾听的需求。\u003c/p>\u003cp>\u003cstrong>（解决）\u003c/strong>今天给大家带来李笑来老师《把时间当作朋友》这本书，书中关于“学会倾听”的内容或许能给大家提供一些方法去应用。熟悉李笑来老师的伙伴们都知道，这本书的理念是“用正确的方式做正确的事情”，有效的自我管理才能在时间的长河中不迷失方向，做最好的自己。书中第六章的内容是“交流”，详细讲了会说话之前的第一步如何先“学会倾听”。\u003c/p>\u003cp>\u003cstrong>（引入）\u003c/strong>在关于倾听的困惑方面，套用笑来老师的一句话：“相信我，你并不孤独。”那现在请大家用2分钟时间阅读拆页，阅读后举手示意我，谢谢。\u003c/p>\u003cp>\u003cstrong>P210\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学会倾听 《把时间当作朋友》\u003c/strong>\u003c/p>\u003cp>正如没有人认为自己不会说一样，几乎没有人认为自己不会听。可事实上，大多数人并不懂得应该如何有效地倾听。从某种意义上讲，交流的有效与否往往更取决于听者而非说者，反过来说，失败的交流往往源自听者的疏忽。不夸张地讲，倾听能力的强弱，几乎能够决定—个人的命运，因为绝大部分时间里，任何一个人的生存和发展都依赖听某些人的话，或者，反过来，依赖某些人听他的话。\u003c/p>\u003cp>人们总以为倾听能力是与生俱来的，并且自然而然地认为阅读能力比倾听能力更难养成（也就想当然地认为阅读比倾听更重要）。这种认识导致正规教育体系在长达10多年的教育过程中，从未有过针对母语的“听力”课程。教师在课堂上对一届又一届的学生重复教授同样的内容，而台下的学生居然永远只有少数能够全面把握教师所讲述的信息——倾听能力的巨大差异也许是这种永恒尴尬的最好解释之一。\u003c/p>\u003cp>人类讲话的速度往往远低于思考的速度，所以所以我们在倾听的过程中常常会出现走神的现象。刚开始走神的时候，持续时间不会太久，也许只有几分之—秒，但就在这间，大脑也能处理许多信号。因此，当大脑“神游”归来之时，我们往往发现自己并未错过什么重要要的东西。于是，大脑开始自动走神，这—次可能要比之前于是更久，因为大脑早已让“证明”过自己游刃有余”。而当再次归来之时，大脑也许还会“印证”自己并未错过什么……于是，走神的嫩越越来越多，时间越来越长……\u003c/p>\u003cp>如这般下去，终究会出现真正错过重要信息的情况。\u003c/p>\u003cp>另外，说者为了讲解清楚来龙去脉，往往不得不把重要的信息，如重要的事实、迂回的说理、意味深远的结论，放在后面。从总体上来看，说者发出的信息越来越重要，可是听者接收的信息却越来越少、越来越零散。\u003c/p>","explains":"\u003cp>在这个拆页中大家可以清晰地看到，经过一次又一次的走神，听者“印证自己并未错过有效信息”的判断很可能只是幻觉。我们的大脑有一种模式拼接能力，在处理零散信息的时候，会不由自主地将它们按照我们自以为有意义、或者是某种之前的经验的方式拼接起来，比如：只听到自己想到的，只看到自己想看到的。这就这沟通的过程中会忽略掉很多信息。\u003c/p>\u003cp>我们也可以看到：“说比听更容易。”然而人类大多时候是需要用沟通的方式来与他人产生协作关系的，倾听也是但是自身也存在这些局限性从而导致协作受阻，为了摆脱在倾听方面的这种局限，下面将提供3条行动建议给大家：\u003c/p>\u003cp>1、\u003cstrong>克制“过早质疑”。\u003c/strong>一旦产生质疑，我们很容易去打断对方的讲述，这就提高了说者有效表达的难度，也增加了我们获得对方讲述全貌的难度。而且这种“打断”体现出听者的排斥态度，其实我们就算需要质疑，也一定要等对方把话说完。\u003c/p>\u003cp>2、\u003cstrong>在倾听的过程中，我们可以利用多余的脑力处理两个方向的信息：“回顾”与“预期”\u003c/strong>。片段中也提出人类产生多余脑力的原因是大脑能够迅速地处理很多信息。这里的回顾是指：“说者刚刚都讲了些什么？”预期就是：“猜想讲着下一步可能会讲什么？”\u003c/p>\u003cp>3、\u003cstrong>我们还需要养成一个习惯：一旦决定倾听，就要主动帮助说者进入“倾诉”状态。\u003c/strong>听者想办法调动自己所有的感官去感受说者的一切表达方式，包括他的眼神、姿态、动作等，随时随刻尽可能地去想象说者正在经历的情绪状态。听者专注、说者也将进入更深的“倾诉”状态。让对方不停说话，才能让听者获取更多的信息，了解对方也就更加全面。\u003c/p>\u003cp>（拆书家A1）\u003c/p>\u003cp>在这我说一个我自己的经历吧，我带的班级一个班长有一天说想找我聊聊，来了就告诉我，她不想当班长了，我一听立马觉得很生气，就噼里啪啦吵她一顿，然后才问她为什么不想当班长了，因为平时和我关系还不错，但这次可能是想着和我谈心来着的，结果被我吵了一顿，很委屈眼圈都红了。其实我这一开始就对她抱着质疑的态度是不是，所以她连理由都没说出来，就被噎回去了。\u003c/p>\u003cp>然后我看她想哭，就连忙问她怎么了？是不是当班长受委屈了，这个时候女孩已经有些赌气了，说没什么就是觉得自己不想干了，太累，其实我知道她不完全是这些原因，但是明显她已经不想和我沟通了，回顾下她刚才的语气和说辞，我知道是我没有耐心听她讲话，已经使她产生了阻抗情绪，谈话也没办法再顺利进行下去了。\u003c/p>\u003cp>其实这次谈话是我主动约的她，既然一开始我是想听她说话来着，但是没控制好自己的情绪，导致她最后一直都不想和我交谈下去了，直到现在也没有因为这个事情再和我沟通过，算是不了了之了，我真的觉得蛮遗憾的，这个女孩以前还挺信任我的，有什么心里话都会和我说，现在闹成这样，真的是不懂得好好听别人说话呀！\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>【催化A2】在工作和生活中，我们是不是总有一些重要的沟通对象，自己很想提升下倾听能力的，或者最近有什么失败、成功的沟通案例吗？\u003c/p>\u003cp>大家：倾听确实是平时我们生活中比较需要的技能，特别是和亲人、好朋友之间，努力听出来话里话，是很重要的事情。\u003c/p>\u003cp>【请学习者编剧本A2】请各小组一起来编一个对话剧本吧，你将如何应用我们刚才说的3点行动建议，去做一个好的聆听者？把设计好的对话摘要写在纸上，时间五分钟，五分钟后我们邀请小伙伴来讲讲他的故事。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>安然：案例是和一位朋友之间的谈话，二人在吃饭的时候闲聊，本意是为了工作室的发展来交流的，结果到了最后不欢而散。她这位朋友就是从来不等对方把话说完，就开始反驳，不耐心聆听她人说话的人，在人际交往中也会让别人对她敬而远之。\u003c/p>\u003cp>结语：今天，大家通过共同学习，以及一个小小的讨论演练，感受了倾听他人话语带来的人际关系互动中的尊重、理解，当一个好的“说者”很容易，做一个好的“听者”却很难，希望大家回去之后，依然按照倾听的3个原则去与家人、朋友沟通，当对方想找我们倾诉的时候，你将用什么样的态度做他们的倾听者。\u003c/p>\u003cp>感谢大家今天的参与，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480922534000,"updated_at":1480922534000,"ria":true},{"id":855,"topic":"做到倾听时让别人倾诉","learn_goal":"学会倾听时让说话者愿意更多的给我们倾诉","remark":"大家都在学习学会倾听，那么学会倾听之前要做什么呢？当然是要让说的人说出来，说的多，说的开心，说的滔滔不绝，那么如何在决定倾听的时候让说话者愿意更多的给我们倾诉？这一次我带领大家学习，如何让一个人更加的愿意和我们倾诉。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"存在","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"1、事件场景 ：\r\n这里有很多喜欢学习的小伙伴，肯定会经常拆书，但是呢，我们的轮值主席天天催促，天天催促，就差用鞭子抽了，拆书家提交的拆书内容还是迟迟迟迟。直到推迟到最后一刻才被逼着急急的做出来，好像我们是拖延症患者。\r\n2、提问：\r\n我们的拆书家懒？我们拆书家是拖延症患者？还是他们想被鞭子抽？\r\n3、影响：\r\n不同的答案对我们的处理这个问题的方法是不一样的，如果承认自己是个懒人，也许最后真的变成懒人了，而且在心理上一但出现我们不能完成的认知过后，就会觉得自己是一个就不能完成计划的人，久而久之就会恶性循环。\r\n4、解决：\r\n从我们的生活经验中我们常常觉得在最后的时间能做完，但是结果总是匆匆忙忙也做不好，这本书里告诉我们，这些都不是本质原因，本质原因是恐惧：内部恐惧和外部恐惧。我们需要接受内部恐惧的事实：只要做事，就一定会出问题，如果不出问题，肯定是在做梦，梦里叫心想事成；我们要知道的外部恐惧：过度的在意外部评价，一个人一旦开始认真做事，被嘲弄，被耻笑的几率将远远高于被夸奖被鼓励的几率。当我们清楚这两个心里问题的时候，只要告诉自己不用怕，去做吧。要相信有很多的人和我们一样存在这样的问题。","ratings_count":0,"texts":[{"id":2707,"quote":"\u003cp>书名：《把时间当做朋友》\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们还要养成一个重要的习惯：一旦决定倾听， 就要主动帮助说者进入“倾诉”状态。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在课堂上、会议中，打断说者往往不礼貌且没有必要， 甚至会浪费他人的时间、破坏他人的注意力。不过，作为听者， 尤其是能被说者看到的听者，给予说者鼓励性的信号会使 说者更容易地进入“倾诉”状态。尽管我个人极端反对欺骗， 但是，我发现哪怕遇到不喜欢的说者和内容（人们往往会因为讨厌内容而讨厌说者，或者反过来，因为讨厌说者而讨厌内容），适度控制自己的反感情绪对获取信息也会有极大的正面作用—既然坐在那里，“听而不闻”就是浪费自己的时间。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;然而，当面对面交流的时候，听者的反应会在很大程度上影响说者的状态。尽管人们讨厌自己讲话时被打断，但是也没有人喜欢对没有任何反应的听众讲话。从本质上来看， 倾诉其实只有两种：第一种是不顾一切地说出来（比如在教堂里隔着纱窗向神父忏悔），第二种是讲给喜欢听的人。所以， 给予说者适当的反应，是听者为了有效倾听必须做的事情。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在自己状态不佳、心不在焉的时候，“马上停止谈话”是对双方都有利的事情。一旦听者决定倾听某人的话，就要想办法调动自己的所有感官去感受说者的一切表达方式，包括 他的眼神、姿态、动作等，随时随刻尽可能地去想象说者正在经历的情绪状态。一旦听者开始有意识地做这些事，就会 不由自主地真正进入“倾听”状态。而后，更为重要的是，由 于听者的专注，说者也将不由自主地进入更深的“倾诉”状态。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;有些读者可能会觉得以上描述不知所云，这是正常的，因为绝大多数人都误以为“听”是一个被动的动作，而“说”是 一个主动的动作。而事实并非总是如此。善于倾听的人往往会付出很大的努力—因为他们早已习惯，所以并不觉得也不可能觉得辛苦。另外，在很多时候，说者尽管在说，但他们的这个动作也许是被动的。回想一下，我们曾有多少次听到一个人在一口气说了很多话之后慨叹：“我怎么会说这些？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;除了情绪上的反应，我们在更多时候需要通过逻辑上的反应来实现有效倾听。如果读者足够敏感的话，就能体会出“那你的意思是……喽？”和“那你的意思是不是……？”之间的微妙区别—前者多少有些武断，容易导致误解；后者却只是清楚的确认，没有任何副作用。为了能够做到清楚的确认， 那些善于沟通的人往往在恰当的时候使用这样的句式：“那你 看我这么理解对不对？……”说者这时会自然而然地想尽一切办法表述清楚，甚至在这个过程中会突然发觉自己的疏忽之处，进而没有压力地进行自我纠正。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;仔细观察一下就会知道，生活中有多少原本认真的交谈最终变成了激烈的争吵。发生这种情况固然有说者的问题， 但更常被忽略却又更为重要的是，听者没有给出恰当的反应—该确认的时候却武断地下了定论，该回应的时候却示以沉默，说者兴高采烈的时候听者却意兴阑珊，说者努力论证的时候听者却过早开始反驳……\u003c/p>","explains":"\u003cp>学习目标：\u003c/p>\u003cp>在跟我完成本次RIA现场学习后，学习者能够清楚知道何时停止倾听，并能切实的掌握倾听的两个技巧：情绪反应和逻辑反应\u003c/p>\u003cp>这个片段略微有点长，但是他很清楚的说出来我们应该如何倾听。\u003c/p>\u003cp>首先他从心里方面给我们阐述了，如果我们决定要听的话，为什么好好倾听？ \u003c/p>\u003cp>1、不好好倾听（打断别人）会浪费大家时间。2、如果带着情绪什么的还必须听是在浪费自己时间，\u003c/p>\u003cp>第二点是：什么是倾述的？是强调人们把内心中所有事情全部诉说，比一般说话要更彻底，一般有2种：第一种是不顾一切地说出来（比如在教堂里隔着纱窗向神父忏悔），第二种是讲给喜欢听的人。\u003c/p>\u003cp>第三点是接下来我们该怎么去做？：（提问小伙伴）\u003c/p>\u003cp>结束倾听：在自己状态不佳、心不在焉的时候，“马上停止谈话”是对双方都有利的事情。\u003c/p>\u003cp>情绪反应：就要想办法调动自己的所有感官去感受说者的一切表达方式，包括 他的眼神、姿态、动作等，随时随刻尽可能地去想象说者正在经历的情绪状态。（刚刚小伙伴回答问题，我很开心的说赞，就是情绪的一个反馈）当然在更多的时候会有更多例子\u003c/p>\u003cp>逻辑反应：通过逻辑上的反应来实现有效倾听。当别人和你描述一件事的时候，首先要听完，听完过后需要和别人确认一下，一个是否的确认比一个结论会更让人舒服。不信？\u003c/p>\u003cp>那么什么是一个好的情绪反应？\u003c/p>\u003cp>举例：小明和小王是好朋友，他们经常一起玩耍，有一次小明爬树不小心摔倒了，后来打上石膏走路一瘸一拐的，经常被别的小伙伴说是瘸子，小明心里委屈心里苦，于是想和小王说说内心的事情。\u003c/p>\u003cp>小明说：小王，你说我就是摔倒了，以后会好的，为什么他们总说我是瘸子？（郁闷生气状）\u003c/p>\u003cp>小王回应：他们怎么能这么说！（生气状态）\u003c/p>\u003cp>小明说：是啊我也觉得不就是一段时间这样么，又不是好不了。（吐槽状）\u003c/p>\u003cp>小王回应：就是就是。（吐槽状）\u003c/p>\u003cp>小明说：他们说话也不想想我这个当事人的心里感受，就图自己嘴里舒服。（发泄状）\u003c/p>\u003cp>小王：对，我觉得也是（同意符合）\u003c/p>\u003cp>小明说：等我好了，让他们看看！（小生气状）\u003c/p>\u003cp>小王：嗯，看看谁的腿更长。\u003c/p>\u003cp>……\u003c/p>\u003cp>大家能感受到小王的情绪回应了吧？那么什么样的情绪回应是要不得的呢？比如又一次我的大学同学难过刚想和我们倾诉一下，我就来了一句：看你一脸被人强奸的样子，来来说说你的苦，让我们快乐一下。结果。。。\u003c/p>\u003cp>总结来说：我们感受对方的情绪（愤怒、悲伤、郁闷、开心、激动等等~），然后自然的表现出来，这就是最好的情绪反应。\u003c/p>\u003cp>那么接下来书中又说到了， \u003c/p>\u003cp>举例：\u003c/p>\u003cp>小明和小王是好朋友，小明去面试后回来说要向小王请教一下面试中遇到的问题。\u003c/p>\u003cp>小明：今天我去XX公司面试的时候，面试官是一个非常漂亮的MM\u003c/p>\u003cp>小王：禽兽，是不是遇到美女面试就激动的说不出话来了，来来，哥教你几种面对美女的技巧\u003c/p>\u003cp>小明：不是，你听我说完，她问了好多问题\u003c/p>\u003cp>小王：问题回答不上来有很多方法，左顾而言他，把她带入到你会的地方来，来来，哥教你几种话术\u003c/p>\u003cp>小明：不是，我没有问题了。谢谢你的帮助。\u003c/p>\u003cp>小王：你这些都懂了是吧？\u003c/p>\u003cp>这就是一个即打断别人，又断章取义的沟通。在对话中有直接给评判结果，有直接给评判式反问：你这些都懂了是吧？，这些都不是一个好的逻辑反应，正常的应该以一个谈到的形式反问：你说的是不是这个意思？或者是：我理解的是这个，不知道对不对。\u003c/p>\u003cp>所以生活中我们做到有效倾听，有让人倾诉的方法是\u003c/p>\u003cp>1、不要打断别人，不带情绪倾听\u003c/p>\u003cp>2、自己状态不行就结束谈话\u003c/p>\u003cp>3、给予情绪反应（提问方法是？）我们感受对方的情绪（愤怒、悲伤、郁闷、开心、激动等等~），然后自然的表现出来，这就是最好的情绪反应。\u003c/p>\u003cp>4、给予逻辑反应（提问方法是？）一个是不是，比一个你说的是这个更好。\u003c/p>","interaction":"\u003cp>刚刚大家也看到我的例子了，那今天大家是不是已经理解了我说的几个方法了？那接下来大家想想一个小故事情节，就像刚刚的小明和小王一样，想象一下他们之间有话有倾诉，那么这个故事应该怎么样呢？\u003c/p>\u003cp>为什么要倾诉？倾诉的是什么事情？对话是什么？可以联系自己生活中的朋友和自己倾诉的事情来改编一下。\u003c/p>\u003cp>学习者A：\u003c/p>\u003cp>朋友公司有大变动，有许多烦心的事情，于是找我倾述一下。\u003c/p>\u003cp>B：最近怎么样？感觉好久不见\u003c/p>\u003cp>A：是啊，时间过的好快，我最近还好，你呢？（反馈）\u003c/p>\u003cp>B：最近状况有些小坑，公司大变动，部门合并，工作了翻一番，而且没有涨工资的打算\u003c/p>\u003cp>A：这么啃爹！那你打算怎么办？（情绪反馈）\u003c/p>\u003cp>B：下一步准备去找领导谈谈工资，谈不好就准备走。\u003c/p>\u003cp>A：你的意思是不是说，如果不涨工资就要离职找新工作？（逻辑反馈）\u003c/p>\u003cp>B：也不一定，如果工作量减少或者增加新人来分担工作也可以。\u003c/p>\u003cp>A：恩，不过这个确实要看情况的。\u003c/p>\u003cp>B：唉~真是突然就这样了。谢谢你能听说我这些\u003c/p>\u003cp>A：哈，不客气，又什么我能帮忙的就说一下。\u003c/p>\u003cp>倾听不仅仅是你坐在他身边，静静的听着就好了，而是要给出反馈，让他能放下身心，愉快的说出来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473142498000,"updated_at":1473142498000,"ria":true},{"id":697,"topic":"想与时间做朋友？你要先学会这一招～","learn_goal":"想与时间做朋友？你要先学会这一招～","remark":"你有没有觉得时间越来越快？一年又过去了，你有没有发现不知道自己去年做了些什么事儿？你读了那么多时间管理的书，结果还是拿时间没办法？你想把时间当敌人征服他，还是想与他好好相处，互相帮助？你要是想与时间当朋友，这周四一定要来西二旗，来听听小桃拆解与时间做朋友的”终极秘籍“！","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"王小桃","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是王小桃，开始拆今天的片段前，我想请大家回想三个问题：1.昨天晚上这个时候你在干什么？2.上周三晚上8点到9点你在干什么？3.上个月第三周的周三晚上8点到9点你在干什么？能准确回答我这三个问题的小伙伴请举手。哦好真棒！我看到大部分的人还是很准确的回忆起来的。我们太忙了，忙到一年到头，还得问“时间都去哪儿了？”（有会唱的吗？）那为了找到时间，更深刻的认识我们的时间，就有必要来看看我今天带来的这本书啦～ \r\nF：这本书书名是《把时间当作朋友》作者是李笑来，以前是新东方的一位老师，这本书从心智成长的角度来谈时间管理，指出时间管理是个人成长的关键所在。 A：这本书最大的特点是它换了个角度看时间，他认为我们不需要把时间看成敌人，一味想着去管理他、驯服他，而是应该把它当作朋友，去了解他、感知他。B：从这个角度出发，让我们从这本书里不仅能学到与时间相处的方法，还可以让我们更深刻的了解我们的心智、开启我们的心智。 回到我今天的主题，想和时间做朋友，我们就要先了解时间，我们来看看今天的片段。","ratings_count":0,"texts":[{"id":2180,"quote":null,"explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>好的，我看到大部分人已经读完了，下面我来讲解一下这个片段。&nbsp; &nbsp; 这个片段里提到两种日志”事件日志“和”事件-时间日志“，只记事件的日志是初级本领，今天我们要关注的是后者“事件-时间日志”，它比较好理解，就是记录下你经历的事件，并写上事件花费的时间。这里需要强调的是事件，事件是指除了自己经历的事件之外一概不记，而且尽量不记感想，不记感受，只记录事件本身。为了让大家更好的理解，我以这两天坐车上班这件事为例子，讲解一下如何使用“事件-时间”日志。昨天早上我坐车上班，很顺利，半个小时就到公司。日志里我会写“3月30日 &nbsp; 坐车上班 &nbsp; 7：50-8：20，花费30分钟；今天早上，我出门晚了一点，结果碰到大堵车，一个半小时才到公司，郁闷极了。这里郁闷极了是我的感受，不需要记到日志里，那今天早上针对上班交通这件事，我这样记”3月31日，坐车上班，堵车，90分钟。”&nbsp; （质疑1） &nbsp; 大家都知道那个爱接茬的小明吧（不是我师父王小明哈），小明可能会说“这个事太麻烦了，把一天里做的事和用的时间都记录下来，臣妾做不到啊～”很多事情，如果你真的决定去做，办法就多的是，而且开始后，才发现没有那么难，你看李笑来把本子栓在马桶对面的墙上，每天10分钟就能回忆完一天的事。你也可以像我一样找一个时间记录的APP，比如我在最强推荐里推荐的atimelogger，随时记录，还能出报表。&nbsp;&nbsp;&nbsp; &nbsp; 最后，我想再提一点，当我们刚刚开始的时候，不要追求完美，也许我们会忘了记录，或者感知不那么精确，没关系，先把这件事做起来，哪怕一天只记录了两件事情，你就当你是和你时间的这个朋友打了个招呼，说“哦，原来你在这里”\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>【A2分步催化1】拆书家提问设计（逐字稿）：现在，大家手里都有笔吧？没有笔的可以用手机里的记事本。请听我的指令：大家认真回忆一下从今天早上你睁开眼睛，到7点前我们活动开始为止，这大约12个小时里，你都做了些什么事？比如早上一般是起床、吃早饭、去上班，上班的时候处理邮件等等，你能想起来几件事呢，花费的时间是多少？请大家写下来，格式像手里的片段中A2部分的示例一样，每条都有标号，后面加上花费的时间。写完后我要请几个小伙伴分享一下。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>【A2分步催化2】拆书家提问设计（逐字稿）：好的，刚才我们针对事件-时间日志做了一个小练习，那现在请大家规划一下，从明天开始的未来一周内，你会如何去运用这个方法呢？是随身带个本和笔，或者在手机里随手记录呢？还是打算一天结束后，在一个固定的时间做记录？\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>我今天的分享就到这里，刚才大家都已经做了一个事件时间记录的计划，欢迎大家在计划实施之后，在我们的大群里分享你的感受，你可能会对你的时间有让你吃惊的认识，但是无论你有什么感觉，我想用书里那句话“相信我，你并不孤独。”\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1470406898000,"updated_at":1470406898000},{"id":627,"topic":"如何善用你的社交时间？","learn_goal":"如何善用你的社交时间？","remark":"如何善用你的社交时间？","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"熊赳赳爱学习","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"111","ratings_count":0,"texts":[],"created_at":1468997536000,"updated_at":1468997536000},{"id":361,"topic":"TF1-1练习","learn_goal":"TF1-1拆解","remark":"李笑来成名作品","level":"TF1-1","duration":15,"status":0,"type":1,"chaishujia":{"username":"雪野兔","city":"济南"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1463885952000,"updated_at":1463885952000},{"id":353,"topic":"沟通","learn_goal":"学习聆听和回顾","remark":"沟通的方式技巧如此多，但我们往往忽略最基本的聆听，本周三让我们一去学习并实操如何聆听和反馈","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"卢珊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我今天拆解的片段来自于李笑来的《把时间当作朋友》\r\nF：《把时间当做朋友》，此书的作者李笑来原是新东方的老师，目前是一位咨询合伙人。书中一共八个章节，目录清晰简洁的表达了每个章节的核心内容。此书一直是自我管理、人生规划书籍类别中的畅销者，may姐都曾经拆解过此书喔，可想它的魅力所在。\r\nA：此书开篇的阅读说明很独特，说到“这本书不是时间管理书籍”，它是从心智成长的角度来谈自我积累的过程，通过作者职业生涯的一些事例告诉我我们如何运用心智来和时间做朋友。内容轻松活泼，不但有可爱的插图，还对书中的生僻概念进行了注释，完全省去了百度的动作。\r\nB：。这本书没有时间管理类书籍对于方式技巧的着重描述，更像是从what和how角度去叙述，先理清了我们对待时间的一些看法，通过阅读此书，我们对于学习、思考、甚至沟通交流都会有新的收获。","ratings_count":0,"texts":[],"created_at":1463753932000,"updated_at":1463753932000},{"id":87,"topic":"如何高效的一心二用","learn_goal":"学习一种高效的一心二用的方法","remark":"无论在工作还是生活中我们都有很多事要做。一个一个的去完成这些任务往往让我们身心疲惫，甚至我们常常会抱怨时间不够用。\r\n俗话说『一心不可二用』，但是为了高效的处理堆积如山的任务我们有必要给自己的大脑打造一个『多任务处理系统』，从而在同样的时间内完成更多的任务。\r\n本期活动，跟着拆书家吴桐一起来拆解《把时间当做朋友》，学习一种高效的一心二用的方法。高效工作，享受生活！","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"吴桐","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我叫吴桐，与梧桐树的梧桐同音，也希望我能如同梧桐树一般招到凤凰。我的三个标签是 IT,90后和新手拆书家。今天非常高兴为大家带来我的第二次拆书。我今天拆解的片段来自《把时间当做朋友》，这是一本在时间管理领域非常经典的书籍。或许有的小伙伴在日常的工作生活中会发现自己不能高效的利用时间，做事总是拖拉，无法如期完成自己的计划。如果各位小伙伴希望自己的拖延症，那么本书一定会给你带来帮助。","ratings_count":0,"texts":[{"id":91,"quote":"从发展的角度看，为了提高效率，我们也有必要为自己的大脑打造一个『多任务操作系统』。最直接的办法是尽量将两个任务并行。例如，在跑步的时候听英语，在写文章的时候听音乐，在等班车的时候看书等。养成一个习惯-把要做的事情用纸和笔写下来，把任务落到纸面上，就可以比较容易地分辨出哪些任务是简单而又机械的，哪些任务是相对复杂而又灵活的（对我个人来讲，需要思考的就是『非机械』的），然后，尝试把一个非机械的任务和一个机械的任务搭配起来完成。","explains":"在大家看完这个片段以后我想先和大家分享一下我对这个片段的理解。这个片段为我们介绍了一个让自己一心二用也就是同时进行两个任务的方法。那么，如何让自己能够一心二用呢？首先写出在工作和生活中我们需要做的事情，然后按照原文片段提供的方法把它们分为机械任务和非机械任务。最后，把一个机械任务和一个非机械任务尝试放在一起去完成。比如，我最近在练习英语听力，需要听一些英文的材料，这对我来说是需要思考的。另外，我最近也在通过跑步这种方式健身。这对我来说是不需要思考的。那么，我可以在跑步的过程中听英语材料。这样能够同时完成两个任务节省了大量时间，而且两个任务相互搭配还能让我在完成这两个任务的过程中不觉得单调。如果我们一个一个的去完成每个任务，不但有一些单调，而且也会多花一倍的时间。","interaction":"A1：\r\n 请各位小伙伴4人一组，首先在一张纸上写下自己在工作当中和下班回到家后通常都做哪些事，并把它们按照之前的介绍分为机械任务和非机械任务，然后在小组内进行分享。\r\n学习者分享：在下班回家后需要完成的机械任务有：洗澡，洗衣服。 非机械任务有：做总结，听《逻辑思维》。\r\nA2：\r\n大家利用我今天分享的一心二用法，挑选出一组机械任务和非机械任务，写出自己未来的行动计划。各位小伙伴要注意的是这个计划要有明确的时限，而不是简单的表决心。\r\n学习者分享：\r\n学习者 A:从下周开始我可以在下班回家后一边洗衣服一边听《逻辑思维》。\r\n学习者 B:从下周一开始可以在洗完澡等头发干的同时写文章，不会再一直等着头发干浪费时间。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1453559407000,"updated_at":1453559407000,"ria":true}]};